INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35774, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "間に何も入れないで、じかにすること。", "primary_collocate": null, "pronunciation": "ちょくせつ", "ipa": "tɕokɯsetsɯ", "syllable_count": 4, "sentences": [{"text": "先生に直接聞いてみる。", "target_word": "直接", "complexity_tier": "T3", "furigana": "せんせい ちょくせつ き", "sentence_source": "generated"}, {"text": "彼に直接会って話した。", "target_word": "直接", "complexity_tier": "T3", "furigana": "かれ ちょくせつ あ はな", "sentence_source": "generated"}, {"text": "直接お店に行ってください。", "target_word": "直接", "complexity_tier": "T3", "furigana": "ちょくせつ みせ い", "sentence_source": "generated"}, {"text": "荷物を直接家に送った。", "target_word": "直接", "complexity_tier": "T3", "furigana": "にもつ ちょくせつ いえ おく", "sentence_source": "generated"}, {"text": "社長と直接話せてうれしい。", "target_word": "直接", "complexity_tier": "T3", "furigana": "しゃちょう ちょくせつ はな", "sentence_source": "generated"}, {"text": "直接手で触らないでね。", "target_word": "直接", "complexity_tier": "T3", "furigana": "ちょくせつ て さわ", "sentence_source": "generated"}, {"text": "答えを直接書いてもいい。", "target_word": "直接", "complexity_tier": "T3", "furigana": "こた ちょくせつ か", "sentence_source": "generated"}, {"text": "その話は直接聞いていない。", "target_word": "直接", "complexity_tier": "T3", "furigana": "はなし ちょくせつ き", "sentence_source": "generated"}, {"text": "日光が直接当たる場所だ。", "target_word": "直接", "complexity_tier": "T3", "furigana": "にっこう ちょくせつ あ ばしょ", "sentence_source": "generated"}, {"text": "母に直接お礼を言った。", "target_word": "直接", "complexity_tier": "T3", "furigana": "はは ちょくせつ れい い", "sentence_source": "generated"}], "morphological_forms": [{"form": "直接的", "label": "派生"}, {"form": "直接的に", "label": "派生"}, {"form": "直接税", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | 間に何も入れずじかに", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::js