INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35808, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっと続くこと。", "primary_collocate": null, "pronunciation": "じぞく", "ipa": "dʑizokɯ", "syllable_count": 3, "sentences": [{"text": "この薬の効果は六時間持続する。", "target_word": "持続", "complexity_tier": "T3", "furigana": "くすり こうか ろくじかん じぞく", "sentence_source": "generated"}, {"text": "集中力を持続させるのは難しい。", "target_word": "持続", "complexity_tier": "T3", "furigana": "しゅうちゅうりょく じぞく むずか", "sentence_source": "generated"}, {"text": "やる気の持続が大切だ。", "target_word": "持続", "complexity_tier": "T3", "furigana": "き じぞく たいせつ", "sentence_source": "generated"}, {"text": "暑さが一週間持続している。", "target_word": "持続", "complexity_tier": "T3", "furigana": "あつ いっしゅうかん じぞく", "sentence_source": "generated"}, {"text": "持続できる練習方法を考えた。", "target_word": "持続", "complexity_tier": "T3", "furigana": "じぞく れんしゅう ほうほう かんが", "sentence_source": "generated"}, {"text": "痛みの持続時間を医者に話した。", "target_word": "持続", "complexity_tier": "T3", "furigana": "いた じぞく じかん いしゃ はな", "sentence_source": "generated"}, {"text": "この電池は長く持続する。", "target_word": "持続", "complexity_tier": "T3", "furigana": "でんち なが じぞく", "sentence_source": "generated"}, {"text": "良い関係を持続したいと思う。", "target_word": "持続", "complexity_tier": "T3", "furigana": "よ かんけい じぞく おも", "sentence_source": "generated"}, {"text": "体力の持続には睡眠が必要だ。", "target_word": "持続", "complexity_tier": "T3", "furigana": "たいりょく じぞく すいみん ひつよう", "sentence_source": "generated"}, {"text": "笑顔を持続するのは大変だ。", "target_word": "持続", "complexity_tier": "T3", "furigana": "えがお じぞく たいへん", "sentence_source": "generated"}], "morphological_forms": [{"form": "持続する", "label": "派生"}, {"form": "持続的", "label": "派生"}, {"form": "持続力", "label": "派生"}, {"form": "持続可能", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 状態がずっと続くこと", "collocate_grounding": {"status": "no_sourc