INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35824, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "道や流れなどが、あちこちで切れてしまうこと。", "primary_collocate": null, "pronunciation": "すんだん", "ipa": "sɯndaɴ", "syllable_count": 4, "sentences": [{"text": "大雨で道路が寸断された。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "おおあめ どうろ すんだん", "sentence_source": "generated"}, {"text": "地震で線路が寸断されている。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "じしん せんろ すんだん", "sentence_source": "generated"}, {"text": "道の寸断で村に行けなくなった。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "みち すんだん むら い", "sentence_source": "generated"}, {"text": "雪で山の道が寸断された。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "ゆき やま みち すんだん", "sentence_source": "generated"}, {"text": "橋が落ちて道路が寸断された。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "はし お どうろ すんだん", "sentence_source": "generated"}, {"text": "寸断された道を急いで直している。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "すんだん みち いそ なお", "sentence_source": "generated"}, {"text": "台風による寸断が心配だ。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "たいふう すんだん しんぱい", "sentence_source": "generated"}, {"text": "水道管が寸断され、水が止まった。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "すいどうかん すんだん みず と", "sentence_source": "generated"}, {"text": "線路の寸断で電車が止まった。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "せんろ すんだん でんしゃ と", "sentence_source": "generated"}, {"text": "土砂で道が寸断されてしまった。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "どしゃ みち すんだん", "sentence_source": "generated"}], "morphological_forms": [{"form": "寸断する", "label": "派生"}, {"form": "寸断される", "label": "派生"}, {"form": "寸断された", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 道や線が途中で切れること", "collocate_grounding": {"status": "no_source", "reason": "no colloc