INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35825, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事のつながりや流れが、途中で断たれること。", "primary_collocate": null, "pronunciation": "すんだん", "ipa": "sɯndaɴ", "syllable_count": 4, "sentences": [{"text": "停電で通信が寸断された。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "ていでん つうしん すんだん", "sentence_source": "generated"}, {"text": "物流の寸断で店に物がない。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "ぶつりゅう すんだん みせ もの", "sentence_source": "generated"}, {"text": "会話が何度も寸断された。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "かいわ なんど すんだん", "sentence_source": "generated"}, {"text": "連絡の寸断が一日続いた。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "れんらく すんだん いちにち つづ", "sentence_source": "generated"}, {"text": "電話で集中が寸断されてしまう。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "でんわ しゅうちゅう すんだん", "sentence_source": "generated"}, {"text": "寸断された情報をつなげて考えた。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "すんだん じょうほう かんが", "sentence_source": "generated"}, {"text": "戦争で人々の交流が寸断された。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "せんそう ひとびと こうりゅう すんだん", "sentence_source": "generated"}, {"text": "供給の寸断を防ぎたい。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "きょうきゅう すんだん ふせ", "sentence_source": "generated"}, {"text": "ネットの寸断で仕事が止まった。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "すんだん しごと と", "sentence_source": "generated"}, {"text": "睡眠が寸断されると疲れる。", "target_word": "寸断", "complexity_tier": "T3", "furigana": "すいみん すんだん つか", "sentence_source": "generated"}], "morphological_forms": [{"form": "寸断する", "label": "派生"}, {"form": "寸断される", "label": "派生"}, {"form": "寸断された", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | つながりや流れが断たれること", "collocate_grounding": {"status": "no_source", "reason": "n