INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35787, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "動機", "is_correct": true, "explanation": "どうき。正解。"}, {"text": "道具", "is_correct": false, "explanation": "どうぐ。最後のモーラ「き」が「ぐ」に変わる一モーラ差。"}, {"text": "動詞", "is_correct": false, "explanation": "どうし。最後のモーラ「き」が「し」に変わる一モーラ差。"}, {"text": "陶器", "is_correct": false, "explanation": "とうき。最初の「ど」が清音「と」になる清濁の対立。"}, {"text": "土器", "is_correct": false, "explanation": "どき。「どう」の長音がない長短の対立。"}], "explanations": {"動機": "どうき。正解。", "道具": "どうぐ。最後のモーラ「き」が「ぐ」に変わる一モーラ差。", "動詞": "どうし。最後のモーラ「き」が「し」に変わる一モーラ差。", "陶器": "とうき。最初の「ど」が清音「と」になる清濁の対立。", "土器": "どき。「どう」の長音がない長短の対立。"}, "sentence_index": null, "correct_answer": "動機"}, "level_3": {"options": [{"text": "動機", "is_correct": true, "explanation": "「日本語を学ぶ」理由を尋ねる文なので「動機」が合う。"}, {"text": "値段", "is_correct": false, "explanation": "値段は学ぶ行為の理由にならない。"}, {"text": "机", "is_correct": false, "explanation": "具体物で、学ぶ理由を表せない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は学ぶことの理由を表さない。"}], "explanations": {"動機": "「日本語を学ぶ」理由を尋ねる文なので「動機」が合う。", "値段": "値段は学ぶ行為の理由にならない。", "机": "具体物で、学ぶ理由を表せない。", "天気": "天気は学ぶことの理由を表さない。"}, "sentence_index": 0, "correct_answer": "動機"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の動機を一冊買った。", "explanation": "助数詞の誤り。動機は物ではないので「一冊」で数えられない。"}, {"text": "動機で彼女が単純だった。", "explanation": "助詞の誤り。「動機が単純だ」とすべきで、「で」では意味が通らない。"}, {"text": "彼女の動機はとても青かった。", "explanation": "意味の誤り。動機は理由であり、色を持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35787, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は動機を食べて元気になった。", "corrected_sentence": "私は動機があって元気になった。", "error_description": "「動機」は食べられる物ではなく、行動の理由を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35787, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置には「を」が文法的に必要。"}, {"text": "が", "is_correct": false, "explanation": "「動機が先生に話した」では動機が話し手になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「話す」の目的語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所で、ここでは非文になる。"}], "correct_answer": "を", "explanations": {"を": "この位置には「を」が文法的に必要。", "が": "「動機が先生に話した」では動機が話し手になり不自然。", "へ": "「へ」は方向を表し、「話す」の目的語を示せない。", "で": "「で」は手段・場所で、ここでは非文になる。"}, "error_tags": {"が": "object_marking", "へ": "direction", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35787, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "動機", "is_correct": true, "explanation": "どうき。正解。"}, {"text": "同意", "is_correct": false, "explanation": "どうい。「き」が「い」に変わる一モーラ差。"}, {"text": "冬季", "is_correct": false, "explanation": "とうき。語頭の濁音「ど」が清音「と」になる清濁の差。"}, {"text": "道具", "is_correct": false, "explanation": "どうぐ。末尾「き」と「ぐ」の一モーラ差。"}, {"text": "土器", "is_correct": false, "explanation": "どき。長音「う」の有無による長短の差。"}], "explanations": {"動機": "どうき。正解。", "同意": "どうい。「き」が「い」に変わる一モーラ差。", "冬季": "とうき。語頭の濁音「ど」が清音「と」になる清濁の差。", "道具": "どうぐ。末尾「き」と「ぐ」の一モーラ差。", "土器": "どき。長音「う」の有無による長短の差。"}, "sentence_index": null, "correct_answer": "動機"}, "level_3": {"options": [{"text": "動機", "is_correct": true, "explanation": "「強い〜があれば頑張れる」は行動の理由を表す「動機」が合う。"}, {"text": "屋根", "is_correct": false, "explanation": "屋根があっても頑張れる理由にはならない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題があれば頑張れる、では意味が逆に近く不自然。"}, {"text": "雨", "is_correct": false, "explanation": "強い雨があれば頑張れる、は意味が通らない。"}], "explanations": {"動機": "「強い〜があれば頑張れる」は行動の理由を表す「動機」が合う。", "屋根": "屋根があっても頑張れる理由にはならない。", "宿題": "宿題があれば頑張れる、では意味が逆に近く不自然。", "雨": "強い雨があれば頑張れる、は意味が通らない。"}, "sentence_index": 6, "correct_answer": "動機"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "動機は人によって違う味がする。", "explanation": "意味の誤り。動機は理由なので味はしない。"}, {"text": "動機を人によって違う。", "explanation": "助詞の誤り。主語は「は／が」で、「を」は使えない。"}, {"text": "動機は人によって違う匂いがする。", "explanation": "意味の誤り。動機は理由なので匂いはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35787, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この動機はとても甘くておいしい。", "corrected_sentence": "この動機はとても単純でわかりやすい。", "error_description": "「動機」は理由なので、味を表す「甘い」「おいしい」とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35787, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置には「を」が文法的に必要。"}, {"text": "に", "is_correct": false, "explanation": "「聞く」の内容を示すのは「を」で、「に」では相手の意味になり不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所で、「聞く」の内容を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較・起点で、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "この位置には「を」が文法的に必要。", "に": "「聞く」の内容を示すのは「を」で、「に」では相手の意味になり不自然。", "で": "「で」は手段・場所で、「聞く」の内容を示せない。", "より": "「より」は比較・起点で、目的語を示せない。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "より": "other"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35808, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "持続", "is_correct": true, "explanation": "じぞく。正解。"}, {"text": "地獄", "is_correct": false, "explanation": "じごく。二番目のモーラ「ぞ」が「ご」に変わる一モーラ差。"}, {"text": "自足", "is_correct": false, "explanation": "じそく。「ぞ」が清音「そ」になる清濁の対立。"}, {"text": "氏族", "is_correct": false, "explanation": "しぞく。語頭「じ」が清音「し」になる清濁の対立。"}, {"text": "家族", "is_correct": false, "explanation": "かぞく。語頭「じ」が「か」に変わる一モーラ差。"}], "explanations": {"持続": "じぞく。正解。", "地獄": "じごく。二番目のモーラ「ぞ」が「ご」に変わる一モーラ差。", "自足": "じそく。「ぞ」が清音「そ」になる清濁の対立。", "氏族": "しぞく。語頭「じ」が清音「し」になる清濁の対立。", "家族": "かぞく。語頭「じ」が「か」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "持続"}, "level_3": {"options": [{"text": "持続", "is_correct": true, "explanation": "効果が六時間続くことを表すので「持続」が合う。"}, {"text": "出発", "is_correct": false, "explanation": "効果が出発する、は意味が通らない。"}, {"text": "記入", "is_correct": false, "explanation": "効果を記入するではなく、効果が続く話である。"}, {"text": "卒業", "is_correct": false, "explanation": "効果が六時間卒業する、は非文。"}], "explanations": {"持続": "効果が六時間続くことを表すので「持続」が合う。", "出発": "効果が出発する、は意味が通らない。", "記入": "効果を記入するではなく、効果が続く話である。", "卒業": "効果が六時間卒業する、は非文。"}, "sentence_index": 0, "correct_answer": "持続"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑さが一週間持続して、すぐに終わった。", "explanation": "意味の誤り。持続は長く続くことなので「すぐに終わった」と矛盾する。"}, {"text": "暑さが一週間持続してある。", "explanation": "アスペクトの誤り。自動詞的な「持続」に「てある」は使えない。"}, {"text": "一枚の暑さが持続している。", "explanation": "助数詞の誤り。暑さは「枚」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35808, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬の効果は六時間持続して止まった。", "corrected_sentence": "この薬の効果は六時間持続した。", "error_description": "「持続」は続くことなので、同時に「止まった」と言うと矛盾する。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35808, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置には「を」が文法的に必要。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所で、「させる」の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向で、目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点で、「させる」の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "この位置には「を」が文法的に必要。", "で": "「で」は手段・場所で、「させる」の対象を示せない。", "へ": "「へ」は方向で、目的語にならない。", "から": "「から」は起点で、「させる」の対象を示せない。"}, "error_tags": {"で": "instrument", "へ": "direction", "から": "source_vs_goal"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "続いていたことが途中で止まること。持続の対義語。"}, {"text": "継続", "is_correct": false, "explanation": "続けることで、類義語であり対義語ではない。"}, {"text": "維持", "is_correct": false, "explanation": "状態を保つことで、類義に近い。"}, {"text": "延長", "is_correct": false, "explanation": "長くすることで、対義関係にない。"}], "correct_answer": "中断", "explanations": {"中断": "続いていたことが途中で止まること。持続の対義語。", "継続": "続けることで、類義語であり対義語ではない。", "維持": "状態を保つことで、類義に近い。", "延長": "長くすることで、対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35808, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "持続", "is_correct": true, "explanation": "じぞく。正解。"}, {"text": "地蔵", "is_correct": false, "explanation": "じぞう。最後のモーラ「く」が「う」に変わる一モーラ差。"}, {"text": "時速", "is_correct": false, "explanation": "じそく。「ぞ」が清音「そ」になる清濁の差。"}, {"text": "遺族", "is_correct": false, "explanation": "いぞく。語頭「じ」が「い」に変わる一モーラ差。"}, {"text": "貴族", "is_correct": false, "explanation": "きぞく。語頭「じ」が「き」に変わる一モーラ差。"}], "explanations": {"持続": "じぞく。正解。", "地蔵": "じぞう。最後のモーラ「く」が「う」に変わる一モーラ差。", "時速": "じそく。「ぞ」が清音「そ」になる清濁の差。", "遺族": "いぞく。語頭「じ」が「い」に変わる一モーラ差。", "貴族": "きぞく。語頭「じ」が「き」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "持続"}, "level_3": {"options": [{"text": "持続", "is_correct": true, "explanation": "電池の力が長く続くことを表すので「持続」が合う。"}, {"text": "到着", "is_correct": false, "explanation": "電池が長く到着する、は意味が通らない。"}, {"text": "相談", "is_correct": false, "explanation": "電池が相談する、は非文。"}, {"text": "料理", "is_correct": false, "explanation": "電池が料理する、は意味が通らない。"}], "explanations": {"持続": "電池の力が長く続くことを表すので「持続」が合う。", "到着": "電池が長く到着する、は意味が通らない。", "相談": "電池が相談する、は非文。", "料理": "電池が料理する、は意味が通らない。"}, "sentence_index": 6, "correct_answer": "持続"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "笑顔が持続するのを大変だ。", "explanation": "助詞の誤り。「〜のは大変だ」が正しく、「を」は使えない。"}, {"text": "一匹の笑顔を持続する。", "explanation": "助数詞の誤り。笑顔は「匹」で数えない。"}, {"text": "笑顔を一瞬だけ持続するのは大変だ。", "explanation": "意味の誤り。持続は長く続くことで「一瞬だけ」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_