INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35824, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "寸断", "is_correct": true, "explanation": "すんだん。正解。"}, {"text": "分断", "is_correct": false, "explanation": "ぶんだん。語頭「す」が「ぶ」に変わる一モーラ差。"}, {"text": "診断", "is_correct": false, "explanation": "しんだん。語頭「す」が「し」に変わる一モーラ差。"}, {"text": "判断", "is_correct": false, "explanation": "はんだん。語頭「す」が「は」に変わる一モーラ差。"}, {"text": "三段", "is_correct": false, "explanation": "さんだん。語頭「す」が「さ」に変わる一モーラ差。"}], "explanations": {"寸断": "すんだん。正解。", "分断": "ぶんだん。語頭「す」が「ぶ」に変わる一モーラ差。", "診断": "しんだん。語頭「す」が「し」に変わる一モーラ差。", "判断": "はんだん。語頭「す」が「は」に変わる一モーラ差。", "三段": "さんだん。語頭「す」が「さ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "寸断"}, "level_3": {"options": [{"text": "寸断", "is_correct": true, "explanation": "大雨で道路があちこち切れたことを表すので「寸断」が合う。"}, {"text": "建設", "is_correct": false, "explanation": "大雨で道路が建設された、は因果が合わない。"}, {"text": "完成", "is_correct": false, "explanation": "大雨で道路が完成する、は意味が通らない。"}, {"text": "掃除", "is_correct": false, "explanation": "大雨で道路が掃除された、は不自然。"}], "explanations": {"寸断": "大雨で道路があちこち切れたことを表すので「寸断」が合う。", "建設": "大雨で道路が建設された、は因果が合わない。", "完成": "大雨で道路が完成する、は意味が通らない。", "掃除": "大雨で道路が掃除された、は不自然。"}, "sentence_index": 0, "correct_answer": "寸断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪を山の道が寸断された。", "explanation": "助詞の誤り。原因は「で」で示し、「を」は使えない。"}, {"text": "雪で一冊の道が寸断された。", "explanation": "助数詞の誤り。道は「冊」で数えない。"}, {"text": "雪で山の道が寸断されてある。", "explanation": "アスペクトの誤り。受身に「てある」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
