INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35825, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "寸断", "is_correct": true, "explanation": "すんだん。正解。"}, {"text": "船団", "is_correct": false, "explanation": "せんだん。語頭「す」が「せ」に変わる一モーラ差。"}, {"text": "軍団", "is_correct": false, "explanation": "ぐんだん。語頭「す」が「ぐ」に変わる一モーラ差。"}, {"text": "寸前", "is_correct": false, "explanation": "すんぜん。「だ」が「ぜ」に変わる一モーラ差。"}, {"text": "算段", "is_correct": false, "explanation": "さんだん。語頭「す」が「さ」に変わる一モーラ差。"}], "explanations": {"寸断": "すんだん。正解。", "船団": "せんだん。語頭「す」が「せ」に変わる一モーラ差。", "軍団": "ぐんだん。語頭「す」が「ぐ」に変わる一モーラ差。", "寸前": "すんぜん。「だ」が「ぜ」に変わる一モーラ差。", "算段": "さんだん。語頭「す」が「さ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "寸断"}, "level_3": {"options": [{"text": "寸断", "is_correct": true, "explanation": "戦争で人々の交流が断たれたことを表すので「寸断」が合う。"}, {"text": "発表", "is_correct": false, "explanation": "交流が発表された、は意味が通らない。"}, {"text": "招待", "is_correct": false, "explanation": "交流が招待された、は不自然。"}, {"text": "予約", "is_correct": false, "explanation": "交流が予約された、は意味が通らない。"}], "explanations": {"寸断": "戦争で人々の交流が断たれたことを表すので「寸断」が合う。", "発表": "交流が発表された、は意味が通らない。", "招待": "交流が招待された、は不自然。", "予約": "交流が予約された、は意味が通らない。"}, "sentence_index": 6, "correct_answer": "寸断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "睡眠を寸断されると疲れる。", "explanation": "助詞の誤り。この文では主語の「が」が自然で、「を」は不自然。"}, {"text": "一本の睡眠が寸断されると疲れる。", "explanation": "助数詞の誤り。睡眠は「本」で数えない。"}, {"text": "睡眠が寸断されてあると疲れる。", "explanation": "アスペクトの誤り。受身に「てある」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
