INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35834, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "対処", "is_correct": true, "explanation": "たいしょ。正解。"}, {"text": "大将", "is_correct": false, "explanation": "たいしょう。最後に長音が付く長短の対立。"}, {"text": "退社", "is_correct": false, "explanation": "たいしゃ。最後のモーラ「しょ」が「しゃ」に変わる一モーラ差。"}, {"text": "楷書", "is_correct": false, "explanation": "かいしょ。語頭「た」が「か」に変わる一モーラ差。"}, {"text": "内緒", "is_correct": false, "explanation": "ないしょ。語頭「た」が「な」に変わる一モーラ差。"}], "explanations": {"対処": "たいしょ。正解。", "大将": "たいしょう。最後に長音が付く長短の対立。", "退社": "たいしゃ。最後のモーラ「しょ」が「しゃ」に変わる一モーラ差。", "楷書": "かいしょ。語頭「た」が「か」に変わる一モーラ差。", "内緒": "ないしょ。語頭「た」が「な」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "対処"}, "level_3": {"options": [{"text": "対処", "is_correct": true, "explanation": "問題を解決するために動いたことを表すので「対処」が合う。"}, {"text": "賛成", "is_correct": false, "explanation": "問題に賛成した、は意味が通らない。"}, {"text": "到着", "is_correct": false, "explanation": "問題に到着した、は非文。"}, {"text": "感謝", "is_correct": false, "explanation": "問題に感謝した、は不自然。"}], "explanations": {"対処": "問題を解決するために動いたことを表すので「対処」が合う。", "賛成": "問題に賛成した、は意味が通らない。", "到着": "問題に到着した、は非文。", "感謝": "問題に感謝した、は不自然。"}, "sentence_index": 0, "correct_answer": "対処"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早い対処を火事が広がらなかった。", "explanation": "助詞の誤り。原因・手段は「で」で示す。"}, {"text": "一匹の早い対処で火事が止まった。", "explanation": "助数詞の誤り。対処は「匹」で数えない。"}, {"text": "早い対処で火事が広がらなかってある。", "explanation": "活用・アスペクトの誤り。「なかってある」は非文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
