INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35834, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置には「を」が文法的に必要。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所で、「教える」内容を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向で、目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「対処に教えてもらった」は非文。"}], "correct_answer": "を", "explanations": {"を": "この位置には「を」が文法的に必要。", "で": "「で」は手段・場所で、「教える」内容を示せない。", "へ": "「へ」は方向で、目的語にならない。", "に": "「対処に教えてもらった」は非文。"}, "error_tags": {"で": "instrument", "へ": "direction", "に": "location_vs_target"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放置", "is_correct": true, "explanation": "問題をそのままにして何もしないこと。対処の反対。"}, {"text": "処理", "is_correct": false, "explanation": "問題を片づけることで類義語。"}, {"text": "対応", "is_correct": false, "explanation": "状況に合わせて動くことで類義語。"}, {"text": "報告", "is_correct": false, "explanation": "知らせることで、反対の関係にない。"}], "correct_answer": "放置", "explanations": {"放置": "問題をそのままにして何もしないこと。対処の反対。", "処理": "問題を片づけることで類義語。", "対応": "状況に合わせて動くことで類義語。", "報告": "知らせることで、反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
