INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35834, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "この位置には「の」が文法的に必要。"}, {"text": "が", "is_correct": false, "explanation": "「彼が対処は」は主語が二重になり非文。"}, {"text": "に", "is_correct": false, "explanation": "「彼に対処は」は非文。"}, {"text": "と", "is_correct": false, "explanation": "「彼と対処は」では彼と対処が並列になり意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "この位置には「の」が文法的に必要。", "が": "「彼が対処は」は主語が二重になり非文。", "に": "「彼に対処は」は非文。", "と": "「彼と対処は」では彼と対処が並列になり意味が通らない。"}, "error_tags": {"が": "topic_vs_subject", "に": "location_vs_target", "と": "listing"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放置", "is_correct": true, "explanation": "何も手を打たずにそのままにすること。対処の反対。"}, {"text": "処置", "is_correct": false, "explanation": "手当てをすることで類義語。"}, {"text": "解決", "is_correct": false, "explanation": "問題をなくすことで、対処と同じ方向。"}, {"text": "相談", "is_correct": false, "explanation": "話し合うことで、反対の関係にない。"}], "correct_answer": "放置", "explanations": {"放置": "何も手を打たずにそのままにすること。対処の反対。", "処置": "手当てをすることで類義語。", "解決": "問題をなくすことで、対処と同じ方向。", "相談": "話し合うことで、反対の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35835, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "対処", "is_correct": true, "explanation": "たいしょ。正解。"}, {"text": "大将", "is_correct": false, "explanation": "たいしょう。長音が付くかどうかの長短の対立。"}, {"text": "楷書", "is_correct": false, "explanation": "かいしょ。最初の「た」が「か」に変わる一モーラ差。"}, {"text": "退社", "is_correct": false, "explanation": "たいしゃ。最後の「しょ」が「しゃ」に変わる一モーラ差。"}], "explanations": {"対処": "たいしょ。正解。", "大将": "たいしょう。長音が付くかどうかの長短の対立。", "楷書": "かいしょ。最初の「た」が「か」に変わる一モーラ差。", "退社": "たいしゃ。最後の「しょ」が「しゃ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "対処"}, "level_3": {"options": [{"text": "対処", "is_correct": true, "explanation": "困難に向き合って解決しようとしたことを表すので「対処」が合う。"}, {"text": "入学", "is_correct": false, "explanation": "困難に入学した、は非文。"}, {"text": "挨拶", "is_correct": false, "explanation": "困難に挨拶した、は意味が通らない。"}, {"text": "注文", "is_correct": false, "explanation": "困難に注文した、は不自然。"}], "explanations": {"対処": "困難に向き合って解決しようとしたことを表すので「対処」が合う。", "入学": "困難に入学した、は非文。", "挨拶": "困難に挨拶した、は意味が通らない。", "注文": "困難に注文した、は不自然。"}, "sentence_index": 0, "correct_answer": "対処"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "悩みを一人で対処するのはつらい。", "explanation": "助詞の誤り。「対処する」の対象は「に」で示す。"}, {"text": "悩みに一人で対処するのをつらい。", "explanation": "助詞の誤り。「〜のはつらい」とすべき。"}, {"text": "悩みに三枚で対処するのはつらい。", "explanation": "助数詞の誤り。人数を「枚」で数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '520c67d4-12b7-4cc3-9367-e4925fbb4c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
