INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35849, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物事のまわりにあって、それと関係したり影響したりすること。", "primary_collocate": null, "pronunciation": "とりまく", "ipa": "toɾimakɯ", "syllable_count": 4, "sentences": [{"text": "経済を取り巻く状況が悪くなった。", "target_word": "取り巻く", "complexity_tier": "T3", "furigana": "けいざい と ま じょうきょう わる", "sentence_source": "generated"}, {"text": "この問題を取り巻く意見は様々だ。", "target_word": "取り巻く", "complexity_tier": "T3", "furigana": "もんだい と ま いけん さまざま", "sentence_source": "generated"}, {"text": "試合を取り巻く熱気がすごい。", "target_word": "取り巻く", "complexity_tier": "T3", "furigana": "しあい と ま ねっき", "sentence_source": "generated"}, {"text": "多くの課題が計画を取り巻いている。", "target_word": "取り巻い", "complexity_tier": "T3", "furigana": "おお かだい けいかく と ま", "sentence_source": "generated"}, {"text": "音楽を取り巻く世界を調べた。", "target_word": "取り巻く", "complexity_tier": "T3", "furigana": "おんがく と ま せかい しら", "sentence_source": "generated"}, {"text": "ニュースを取り巻く話題が増えた。", "target_word": "取り巻く", "complexity_tier": "T3", "furigana": "と ま わだい ふ", "sentence_source": "generated"}, {"text": "事件を取り巻く人々に話を聞く。", "target_word": "取り巻く", "complexity_tier": "T3", "furigana": "じけん と ま ひとびと はなし き", "sentence_source": "generated"}, {"text": "選挙を取り巻く空気が変わった。", "target_word": "取り巻く", "complexity_tier": "T3", "furigana": "せんきょ と ま くうき か", "sentence_source": "generated"}, {"text": "スポーツを取り巻く環境は良い。", "target_word": "取り巻く", "complexity_tier": "T3", "furigana": "と ま かんきょう よ", "sentence_source": "generated"}, {"text": "噂がその店を取り巻いていた。", "target_word": "取り巻い", "complexity_tier": "T3", "furigana": "うわさ みせ と ま", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り巻いて", "label": "活用"}, {"form": "取り巻いた", "label": "活用"}, {"form": "取り巻かない", "label": "活用"}, {"form": "取り巻き", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 |