INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35870, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもよくて、好ましいこと。", "primary_collocate": null, "pronunciation": "すてき", "ipa": "sɯteki", "syllable_count": 3, "sentences": [{"text": "素敵なプレゼントをありがとう。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "その服、とても素敵だね。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "ふく", "sentence_source": "generated"}, {"text": "素敵な一日を過ごした。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "いちにち す", "sentence_source": "generated"}, {"text": "彼女の笑顔は素敵だ。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "かのじょ えがお", "sentence_source": "generated"}, {"text": "部屋が素敵に変わった。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "へや か", "sentence_source": "generated"}, {"text": "素敵な先生に会えてうれしい。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "せんせい あ", "sentence_source": "generated"}, {"text": "それは素敵な考えだと思う。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "かんが おも", "sentence_source": "generated"}, {"text": "この店はとても素敵です。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "みせ", "sentence_source": "generated"}, {"text": "素敵な友だちができた。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "とも", "sentence_source": "generated"}, {"text": "君の歌は本当に素敵だった。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "きみ うた ほんとう", "sentence_source": "generated"}], "morphological_forms": [{"form": "素敵な", "label": "活用"}, {"form": "素敵だ", "label": "活用"}, {"form": "素敵に", "label": "活用"}, {"form": "素敵さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | とてもよくて好ましい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NU