INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35871, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "見たり聞いたりして、心が動くほど美しく、気持ちがよい様子。", "primary_collocate": null, "pronunciation": "すてき", "ipa": "sɯteki", "syllable_count": 3, "sentences": [{"text": "素敵な景色に言葉を失った。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "けしき ことば うしな", "sentence_source": "generated"}, {"text": "夜空の星がとても素敵だ。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "よぞら ほし", "sentence_source": "generated"}, {"text": "素敵な音楽が流れている。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "おんがく なが", "sentence_source": "generated"}, {"text": "海が夕日で素敵に光っていた。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "うみ ゆうひ ひか", "sentence_source": "generated"}, {"text": "その絵は本当に素敵だった。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "え ほんとう", "sentence_source": "generated"}, {"text": "素敵な花が庭に咲いている。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "はな にわ さ", "sentence_source": "generated"}, {"text": "彼女の声はとても素敵です。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "かのじょ こえ", "sentence_source": "generated"}, {"text": "雪の町は素敵に見えた。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "ゆき まち み", "sentence_source": "generated"}, {"text": "素敵な映画を見て感動した。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "えいが み かんどう", "sentence_source": "generated"}, {"text": "このドレスの色が素敵だね。", "target_word": "素敵", "complexity_tier": "T3", "furigana": "いろ", "sentence_source": "generated"}], "morphological_forms": [{"form": "素敵な", "label": "活用"}, {"form": "素敵だ", "label": "活用"}, {"form": "素敵に", "label": "活用"}, {"form": "素敵さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 心が動くほど美しい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb,