INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35846, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "構築", "is_correct": true, "explanation": "正解。読みはこうちく。"}, {"text": "工作", "is_correct": false, "explanation": "こうさく。三つ目のモーラ「ち」が「さ」に変わる一モーラ差。"}, {"text": "拘束", "is_correct": false, "explanation": "こうそく。三つ目のモーラ「ち」が「そ」に変わる一モーラ差。"}, {"text": "広角", "is_correct": false, "explanation": "こうかく。三つ目のモーラ「ち」が「か」に変わる一モーラ差。"}, {"text": "硬直", "is_correct": false, "explanation": "こうちょく。三つ目のモーラ「ち」が「ちょ」に変わる一モーラ差。"}], "explanations": {"構築": "正解。読みはこうちく。", "工作": "こうさく。三つ目のモーラ「ち」が「さ」に変わる一モーラ差。", "拘束": "こうそく。三つ目のモーラ「ち」が「そ」に変わる一モーラ差。", "広角": "こうかく。三つ目のモーラ「ち」が「か」に変わる一モーラ差。", "硬直": "こうちょく。三つ目のモーラ「ち」が「ちょ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "構築"}, "level_3": {"options": [{"text": "構築", "is_correct": true, "explanation": "意味：新しい仕組みを組み立てて作ることなので正しい。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：散歩はシステムについて使えない。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：睡眠はシステムを作ることを表さない。"}, {"text": "拍手", "is_correct": false, "explanation": "連語：「システムの拍手」とは言わない。"}], "explanations": {"構築": "意味：新しい仕組みを組み立てて作ることなので正しい。", "散歩": "意味：散歩はシステムについて使えない。", "睡眠": "意味：睡眠はシステムを作ることを表さない。", "拍手": "連語：「システムの拍手」とは言わない。"}, "sentence_index": 0, "correct_answer": "構築"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ネットが構築を手伝っている。", "explanation": "助詞の混同：手伝うのは人で、「ネットの構築」とすべき。"}, {"text": "ネットの構築を手伝ってあった。", "explanation": "アスペクトの誤り：「手伝ってある」とは言わず「手伝っている」が正しい。"}, {"text": "構築をネットの手伝っている。", "explanation": "語順の誤り：「ネットの構築を手伝っている」が正しい語順。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
