INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35846, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「かかる」の主語「時間」を示す。"}, {"text": "を", "is_correct": false, "explanation": "「かかる」は自動詞なので目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、ここでは非文。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表し、ここでは意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「かかる」の主語「時間」を示す。", "を": "「かかる」は自動詞なので目的語の「を」は取れない。", "で": "手段・場所を表し、ここでは非文。", "と": "並列・相手を表し、ここでは意味が通らない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "と": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破壊", "is_correct": true, "explanation": "作り上げることの反対で、壊すことを表す対義語。"}, {"text": "建設", "is_correct": false, "explanation": "作ることを表し、類義語に近い。"}, {"text": "計画", "is_correct": false, "explanation": "作る前の考えで、対義関係はない。"}, {"text": "参加", "is_correct": false, "explanation": "関わることで、構築とは対にならない。"}], "correct_answer": "破壊", "explanations": {"破壊": "作り上げることの反対で、壊すことを表す対義語。", "建設": "作ることを表し、類義語に近い。", "計画": "作る前の考えで、対義関係はない。", "参加": "関わることで、構築とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35846, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "構築", "is_correct": true, "explanation": "正解。読みはこうちく。"}, {"text": "工作", "is_correct": false, "explanation": "こうさく：「ち」と「さ」の一モーラ差。"}, {"text": "高速", "is_correct": false, "explanation": "こうそく：「ち」と「そ」の一モーラ差。"}, {"text": "硬直", "is_correct": false, "explanation": "こうちょく：「ち」と「ちょ」の一モーラ差。"}, {"text": "降格", "is_correct": false, "explanation": "こうかく：「ち」と「か」の一モーラ差。"}], "explanations": {"構築": "正解。読みはこうちく。", "工作": "こうさく：「ち」と「さ」の一モーラ差。", "高速": "こうそく：「ち」と「そ」の一モーラ差。", "硬直": "こうちょく：「ち」と「ちょ」の一モーラ差。", "降格": "こうかく：「ち」と「か」の一モーラ差。"}, "sentence_index": null, "correct_answer": "構築"}, "level_3": {"options": [{"text": "構築", "is_correct": true, "explanation": "意味：友だちとの関係を作り上げるので正しい。"}, {"text": "掃除", "is_correct": false, "explanation": "意味：関係を掃除するとは言わない。"}, {"text": "料理", "is_correct": false, "explanation": "意味：関係は料理するものではない。"}, {"text": "運転", "is_correct": false, "explanation": "連語：「関係を運転する」とは言わない。"}], "explanations": {"構築": "意味：友だちとの関係を作り上げるので正しい。", "掃除": "意味：関係を掃除するとは言わない。", "料理": "意味：関係は料理するものではない。", "運転": "連語：「関係を運転する」とは言わない。"}, "sentence_index": 6, "correct_answer": "構築"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校が新しい制度に構築できた。", "explanation": "助詞の混同：作る対象は「を」で示し「制度を構築」とする。"}, {"text": "学校は新しい制度を構築している昨日。", "explanation": "語順・アスペクトの誤り：「昨日」が文末にあり、時制とも合わない。"}, {"text": "学校は新しい制度を構築れた。", "explanation": "活用の誤り：「構築」は「する」を介して可能形「構築できた」にする。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
