INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35846, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「必要だ」の対象「協力」を示す。"}, {"text": "を", "is_correct": false, "explanation": "「必要だ」は形容動詞で「を」を取らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、ここでは意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「必要だ」の対象「協力」を示す。", "を": "「必要だ」は形容動詞で「を」を取らない。", "へ": "方向を表し、ここでは非文。", "から": "起点を表し、ここでは意味が通らない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "から": "source_vs_goal"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解体", "is_correct": true, "explanation": "組み立てたものをばらばらにすることで、構築の対義語。"}, {"text": "作成", "is_correct": false, "explanation": "作ることで、類義語に近い。"}, {"text": "説明", "is_correct": false, "explanation": "内容を伝えることで、対ではない。"}, {"text": "維持", "is_correct": false, "explanation": "保つことで、構築の反対ではない。"}], "correct_answer": "解体", "explanations": {"解体": "組み立てたものをばらばらにすることで、構築の対義語。", "作成": "作ることで、類義語に近い。", "説明": "内容を伝えることで、対ではない。", "維持": "保つことで、構築の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35848, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "取り巻く", "is_correct": true, "explanation": "正解。読みはとりまく。"}, {"text": "取り付く", "is_correct": false, "explanation": "とりつく：三つ目の「ま」が「つ」に変わる一モーラ差。"}, {"text": "振りまく", "is_correct": false, "explanation": "ふりまく：一つ目の「と」が「ふ」に変わる一モーラ差。"}, {"text": "取り置く", "is_correct": false, "explanation": "とりおく：三つ目の「ま」が「お」に変わる一モーラ差。"}], "explanations": {"取り巻く": "正解。読みはとりまく。", "取り付く": "とりつく：三つ目の「ま」が「つ」に変わる一モーラ差。", "振りまく": "ふりまく：一つ目の「と」が「ふ」に変わる一モーラ差。", "取り置く": "とりおく：三つ目の「ま」が「お」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "取り巻く"}, "level_3": {"options": [{"text": "取り巻く", "is_correct": true, "explanation": "意味：私たちのまわりにある環境を表すので正しい。"}, {"text": "食べる", "is_correct": false, "explanation": "意味：環境を食べるとは言わない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "項構造：「泳ぐ」は「を」で人を取れない。"}, {"text": "忘れる", "is_correct": false, "explanation": "意味：「私たちを忘れる環境」では意味が通らない。"}], "explanations": {"取り巻く": "意味：私たちのまわりにある環境を表すので正しい。", "食べる": "意味：環境を食べるとは言わない。", "泳ぐ": "項構造：「泳ぐ」は「を」で人を取れない。", "忘れる": "意味：「私たちを忘れる環境」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "取り巻く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不安に彼を取り巻いている。", "explanation": "助詞の混同：取り巻く主体は「に」ではなく「が」で示す。"}, {"text": "不安が彼を取り巻いてある。", "explanation": "アスペクトの誤り：「てある」ではなく「ている」を使う。"}, {"text": "不安が彼を取り巻きている。", "explanation": "活用の誤り：「取り巻く」のて形は「取り巻いて」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35848, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちに取り巻く環境が変わった。", "corrected_sentence": "私たちを取り巻く環境が変わった。", "error_description": "助詞の混同：「取り巻く」の対象は「に」ではなく「を」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り巻く", "is_correct": true, "explanation": "名詞「問題」を修飾する辞書形（連体形）が正しい。"}, {"text": "取り巻いて", "is_correct": false, "explanation": "て形は名詞を直接修飾できない。"}, {"text": "取り巻こう", "is_correct": false, "explanation": "意向形は名詞修飾に使わない。"}, {"text": "取り巻けば", "is_correct": false, "explanation": "条件形は名詞を修飾できない。"}], "correct_form": "取り巻く", "base_form": "取り巻く", "form_label": "活用", "sentence_index": 1, "explanations": {"取り巻く": "名詞「問題」を修飾する辞書形（連体形）が正しい。", "取り巻いて": "て形は名詞を直接修飾できない。", "取り巻こう": "意向形は名詞修飾に使わない。", "取り巻けば": "条件形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
