INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35848, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "取り巻く", "is_correct": true, "explanation": "正解。読みはとりまく。"}, {"text": "振りまく", "is_correct": false, "explanation": "ふりまく：最初の「と」と「ふ」の一モーラ差。"}, {"text": "取り組む", "is_correct": false, "explanation": "とりくむ：後半「まく」と「くむ」の差。"}, {"text": "取り込む", "is_correct": false, "explanation": "とりこむ：後半「まく」と「こむ」の差。"}], "explanations": {"取り巻く": "正解。読みはとりまく。", "振りまく": "ふりまく：最初の「と」と「ふ」の一モーラ差。", "取り組む": "とりくむ：後半「まく」と「くむ」の差。", "取り込む": "とりこむ：後半「まく」と「こむ」の差。"}, "sentence_index": null, "correct_answer": "取り巻く"}, "level_3": {"options": [{"text": "取り巻い", "is_correct": true, "explanation": "意味：自然が村のまわりにあることを表すので正しい。"}, {"text": "走っ", "is_correct": false, "explanation": "項構造：「村を走っている」では自然が主語として不自然。"}, {"text": "書い", "is_correct": false, "explanation": "意味：自然が村を書くことはない。"}, {"text": "買っ", "is_correct": false, "explanation": "意味：自然が村を買うことはない。"}], "explanations": {"取り巻い": "意味：自然が村のまわりにあることを表すので正しい。", "走っ": "項構造：「村を走っている」では自然が主語として不自然。", "書い": "意味：自然が村を書くことはない。", "買っ": "意味：自然が村を買うことはない。"}, "sentence_index": 6, "correct_answer": "取り巻い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日本が取り巻く世界は広い。", "explanation": "助詞の混同：まわりにある対象は「を」で示し「日本を取り巻く」とする。"}, {"text": "日本を取り巻か世界は広い。", "explanation": "活用の誤り：名詞を修飾するのは連体形「取り巻く」。"}, {"text": "世界は日本を広い取り巻く。", "explanation": "語順の誤り：修飾の順序が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
