INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35849, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "取り巻く", "is_correct": true, "explanation": "正解。読みはとりまく。"}, {"text": "取り付く", "is_correct": false, "explanation": "とりつく：「ま」と「つ」の一モーラ差。"}, {"text": "振りまく", "is_correct": false, "explanation": "ふりまく：「と」と「ふ」の一モーラ差。"}, {"text": "取り置く", "is_correct": false, "explanation": "とりおく：「ま」と「お」の一モーラ差。"}], "explanations": {"取り巻く": "正解。読みはとりまく。", "取り付く": "とりつく：「ま」と「つ」の一モーラ差。", "振りまく": "ふりまく：「と」と「ふ」の一モーラ差。", "取り置く": "とりおく：「ま」と「お」の一モーラ差。"}, "sentence_index": null, "correct_answer": "取り巻く"}, "level_3": {"options": [{"text": "取り巻く", "is_correct": true, "explanation": "意味：経済のまわりにある状況を表すので正しい。"}, {"text": "歌う", "is_correct": false, "explanation": "意味：経済を歌う状況とは言わない。"}, {"text": "眠る", "is_correct": false, "explanation": "項構造：「眠る」は「を」を取らない。"}, {"text": "洗う", "is_correct": false, "explanation": "意味：経済を洗うことはできない。"}], "explanations": {"取り巻く": "意味：経済のまわりにある状況を表すので正しい。", "歌う": "意味：経済を歌う状況とは言わない。", "眠る": "項構造：「眠る」は「を」を取らない。", "洗う": "意味：経済を洗うことはできない。"}, "sentence_index": 0, "correct_answer": "取り巻く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "多くの課題に計画を取り巻いている。", "explanation": "助詞の混同：取り巻く主体は「に」ではなく「が」で示す。"}, {"text": "多くの課題が計画を取り巻いてある。", "explanation": "アスペクトの誤り：「てある」ではなく「ている」。"}, {"text": "多くの課題が三枚の計画を取り巻いている。", "explanation": "助数詞の誤り：計画は「枚」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
