INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35870, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "素敵", "is_correct": true, "explanation": "正解。読みはすてき。"}, {"text": "無敵", "is_correct": false, "explanation": "むてき：最初の「す」が「む」に変わる一モーラ差。"}, {"text": "指摘", "is_correct": false, "explanation": "してき：最初の「す」が「し」に変わる一モーラ差。"}, {"text": "捨てる", "is_correct": false, "explanation": "すてる：最後の「き」が「る」に変わる一モーラ差。"}, {"text": "ステッキ", "is_correct": false, "explanation": "すてっき：促音の有無の違い。"}, {"text": "捨て子", "is_correct": false, "explanation": "すてご：最後の「き」が「ご」に変わる一モーラ差。"}], "explanations": {"素敵": "正解。読みはすてき。", "無敵": "むてき：最初の「す」が「む」に変わる一モーラ差。", "指摘": "してき：最初の「す」が「し」に変わる一モーラ差。", "捨てる": "すてる：最後の「き」が「る」に変わる一モーラ差。", "ステッキ": "すてっき：促音の有無の違い。", "捨て子": "すてご：最後の「き」が「ご」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "素敵"}, "level_3": {"options": [{"text": "素敵", "is_correct": true, "explanation": "意味：プレゼントがよいものだと感謝する気持ちに合う。"}, {"text": "迷惑", "is_correct": false, "explanation": "意味：迷惑なプレゼントに「ありがとう」は合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "意味：退屈なプレゼントへの感謝は不自然。"}, {"text": "不便", "is_correct": false, "explanation": "意味：不便なプレゼントにお礼は合わない。"}], "explanations": {"素敵": "意味：プレゼントがよいものだと感謝する気持ちに合う。", "迷惑": "意味：迷惑なプレゼントに「ありがとう」は合わない。", "退屈": "意味：退屈なプレゼントへの感謝は不自然。", "不便": "意味：不便なプレゼントにお礼は合わない。"}, "sentence_index": 0, "correct_answer": "素敵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の笑顔は素敵な。", "explanation": "活用の誤り：文末では「素敵だ」とし、「な」で終わらない。"}, {"text": "彼女の笑顔を素敵だ。", "explanation": "助詞の混同：主題は「を」ではなく「は」で示す。"}, {"text": "素敵だ彼女の笑顔は。", "explanation": "語順の誤り：述語が先に出て文が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
