INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35870, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "素敵", "is_correct": true, "explanation": "正解。読みはすてき。"}, {"text": "数滴", "is_correct": false, "explanation": "すうてき：長音の有無。"}, {"text": "最適", "is_correct": false, "explanation": "さいてき：「す」と「さい」の差。"}, {"text": "好き", "is_correct": false, "explanation": "すき：「て」が抜けた形。"}, {"text": "素手", "is_correct": false, "explanation": "すで：「てき」と「で」の差。"}], "explanations": {"素敵": "正解。読みはすてき。", "数滴": "すうてき：長音の有無。", "最適": "さいてき：「す」と「さい」の差。", "好き": "すき：「て」が抜けた形。", "素手": "すで：「てき」と「で」の差。"}, "sentence_index": null, "correct_answer": "素敵"}, "level_3": {"options": [{"text": "素敵", "is_correct": true, "explanation": "意味：考えをほめるのに合う。"}, {"text": "下手", "is_correct": false, "explanation": "連語：「下手な考え」は「と思う」と合わず不自然。"}, {"text": "暗い", "is_correct": false, "explanation": "語域・品詞：い形容詞で「暗いな考え」とは言えない。"}, {"text": "面倒", "is_correct": false, "explanation": "意味：考えを面倒だとは評価しにくい。"}], "explanations": {"素敵": "意味：考えをほめるのに合う。", "下手": "連語：「下手な考え」は「と思う」と合わず不自然。", "暗い": "語域・品詞：い形容詞で「暗いな考え」とは言えない。", "面倒": "意味：考えを面倒だとは評価しにくい。"}, "sentence_index": 6, "correct_answer": "素敵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "君の歌は本当に素敵なだった。", "explanation": "活用の誤り：「素敵だった」とし、「な」は不要。"}, {"text": "君の歌を本当に素敵だった。", "explanation": "助詞の混同：主題は「は」で示す。"}, {"text": "本当に君の素敵だった歌は。", "explanation": "語順の誤り：述語と主題の位置が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
