INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35871, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "素敵", "is_correct": true, "explanation": "正解。読みはすてき。"}, {"text": "無敵", "is_correct": false, "explanation": "むてき：「す」と「む」の一モーラ差。"}, {"text": "指摘", "is_correct": false, "explanation": "してき：「す」と「し」の一モーラ差。"}, {"text": "捨てる", "is_correct": false, "explanation": "すてる：「き」と「る」の一モーラ差。"}, {"text": "ステッキ", "is_correct": false, "explanation": "すてっき：促音の有無。"}], "explanations": {"素敵": "正解。読みはすてき。", "無敵": "むてき：「す」と「む」の一モーラ差。", "指摘": "してき：「す」と「し」の一モーラ差。", "捨てる": "すてる：「き」と「る」の一モーラ差。", "ステッキ": "すてっき：促音の有無。"}, "sentence_index": null, "correct_answer": "素敵"}, "level_3": {"options": [{"text": "素敵", "is_correct": true, "explanation": "意味：言葉を失うほど美しい景色に合う。"}, {"text": "平凡", "is_correct": false, "explanation": "意味：平凡な景色で言葉を失うのは不自然。"}, {"text": "退屈", "is_correct": false, "explanation": "意味：退屈な景色に心は動かない。"}, {"text": "不便", "is_correct": false, "explanation": "意味：便利さの話で景色の美しさと合わない。"}], "explanations": {"素敵": "意味：言葉を失うほど美しい景色に合う。", "平凡": "意味：平凡な景色で言葉を失うのは不自然。", "退屈": "意味：退屈な景色に心は動かない。", "不便": "意味：便利さの話で景色の美しさと合わない。"}, "sentence_index": 0, "correct_answer": "素敵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海が夕日で素敵な光っていた。", "explanation": "活用の誤り：動詞を修飾するときは「素敵に」。"}, {"text": "海を夕日で素敵に光っていた。", "explanation": "助詞の混同：光る主体は「が」で示す。"}, {"text": "海が夕日で素敵に光ってあった。", "explanation": "アスペクトの誤り：「てあった」ではなく「ていた」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
