INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35886, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "斯く", "is_correct": true, "explanation": "正解。読みはかく。"}, {"text": "鍵", "is_correct": false, "explanation": "かぎ：「く」と「ぎ」の一モーラ差。"}, {"text": "家具", "is_correct": false, "explanation": "かぐ：清濁の対立。"}, {"text": "学", "is_correct": false, "explanation": "がく：清濁の対立。"}, {"text": "過去", "is_correct": false, "explanation": "かこ：「く」と「こ」の一モーラ差。"}], "explanations": {"斯く": "正解。読みはかく。", "鍵": "かぎ：「く」と「ぎ」の一モーラ差。", "家具": "かぐ：清濁の対立。", "学": "がく：清濁の対立。", "過去": "かこ：「く」と「こ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "斯く"}, "level_3": {"options": [{"text": "斯く", "is_correct": true, "explanation": "意味：「このようにして」旅が終わったことを表す。"}, {"text": "全く", "is_correct": false, "explanation": "連語：「全くして」とは言わない。"}, {"text": "早く", "is_correct": false, "explanation": "連語：「早くして旅は終わった」は不自然。"}, {"text": "強く", "is_correct": false, "explanation": "意味：「強くして」では文意が通らない。"}], "explanations": {"斯く": "意味：「このようにして」旅が終わったことを表す。", "全く": "連語：「全くして」とは言わない。", "早く": "連語：「早くして旅は終わった」は不自然。", "強く": "意味：「強くして」では文意が通らない。"}, "sentence_index": 0, "correct_answer": "斯く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事件を斯く解決された。", "explanation": "助詞の混同：受身の主語は「は」「が」で示す。"}, {"text": "事件は斯くに解決された。", "explanation": "誤用：副詞「斯く」に「に」は付かない。"}, {"text": "事件は斯くの解決された。", "explanation": "誤用：副詞「斯く」は「の」を介さず動詞を直接修飾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d1e8ca-aa1d-4cb3-a669-8aa5e963527d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
