INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35900, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "音楽のひとつ。歌やメロディーのまとまり。", "primary_collocate": null, "pronunciation": "きょく", "ipa": "kʲokɯ", "syllable_count": 2, "sentences": [{"text": "この曲を毎日歌っています。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく まいにち うた", "sentence_source": "generated"}, {"text": "ピアノで曲をひいた。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく", "sentence_source": "generated"}, {"text": "好きな曲を歌った。", "target_word": "曲", "complexity_tier": "T3", "furigana": "す きょく うた", "sentence_source": "generated"}, {"text": "新しい曲を聞いている。", "target_word": "曲", "complexity_tier": "T3", "furigana": "あたら きょく き", "sentence_source": "generated"}, {"text": "この曲はとても有名だ。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく ゆうめい", "sentence_source": "generated"}, {"text": "彼が作った曲は明るい。", "target_word": "曲", "complexity_tier": "T3", "furigana": "かれ つく きょく あか", "sentence_source": "generated"}, {"text": "曲に合わせて踊った。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく あ おど", "sentence_source": "generated"}, {"text": "この曲を三回続けて歌った。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく さんかい つづ うた", "sentence_source": "generated"}, {"text": "この曲を覚えたい。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく おぼ", "sentence_source": "generated"}, {"text": "静かな曲で眠くなった。", "target_word": "曲", "complexity_tier": "T3", "furigana": "しず きょく ねむ", "sentence_source": "generated"}], "morphological_forms": [{"form": "曲(きょく)", "label": "助数詞"}, {"form": "名曲", "label": "派生"}, {"form": "作曲", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 音楽の一つのまとまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75aa1b