INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35901, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "メロディーやリズムなどでできた、まとまった音楽作品。", "primary_collocate": null, "pronunciation": "きょく", "ipa": "kʲokɯ", "syllable_count": 2, "sentences": [{"text": "彼女は新しい曲をピアノでひいた。", "target_word": "曲", "complexity_tier": "T3", "furigana": "かのじょ あたら きょく", "sentence_source": "generated"}, {"text": "この曲はリズムが速い。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく はや", "sentence_source": "generated"}, {"text": "その曲のメロディーが美しい。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく うつく", "sentence_source": "generated"}, {"text": "曲の最後が特に好きだ。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく さいご とく す", "sentence_source": "generated"}, {"text": "ベートーベンの曲を聞いた。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく き", "sentence_source": "generated"}, {"text": "この曲は三分くらいだ。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく さんぷん", "sentence_source": "generated"}, {"text": "曲を何度も口ずさんだ。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく なんど くち", "sentence_source": "generated"}, {"text": "バンドが曲を演奏している。", "target_word": "曲", "complexity_tier": "T3", "furigana": "きょく えんそう", "sentence_source": "generated"}, {"text": "映画の曲が心に残った。", "target_word": "曲", "complexity_tier": "T3", "furigana": "えいが きょく こころ のこ", "sentence_source": "generated"}, {"text": "最後の曲は静かだった。", "target_word": "曲", "complexity_tier": "T3", "furigana": "さいご きょく しず", "sentence_source": "generated"}], "morphological_forms": [{"form": "曲(きょく)", "label": "助数詞"}, {"form": "名曲", "label": "派生"}, {"form": "作曲", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | まとまった一つの音楽作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1',