INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35887, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "斯く", "is_correct": true, "explanation": "正解。「かく」と読む。"}, {"text": "家具", "is_correct": false, "explanation": "「かぐ」。二拍目が清音「く」と濁音「ぐ」で違う。"}, {"text": "過去", "is_correct": false, "explanation": "「かこ」。二拍目が「く」と「こ」で違う。"}, {"text": "傘", "is_correct": false, "explanation": "「かさ」。二拍目が「く」と「さ」で違う。"}, {"text": "柵", "is_correct": false, "explanation": "「さく」。一拍目が「か」と「さ」で違う。"}], "explanations": {"斯く": "正解。「かく」と読む。", "家具": "「かぐ」。二拍目が清音「く」と濁音「ぐ」で違う。", "過去": "「かこ」。二拍目が「く」と「こ」で違う。", "傘": "「かさ」。二拍目が「く」と「さ」で違う。", "柵": "「さく」。一拍目が「か」と「さ」で違う。"}, "sentence_index": null, "correct_answer": "斯く"}, "level_3": {"options": [{"text": "斯く", "is_correct": true, "explanation": "「斯くして」で「このようにして」の意味になり、文が自然。"}, {"text": "高く", "is_correct": false, "explanation": "形容詞の連用形で、「高くして旅が終わる」は意味が通らない。"}, {"text": "全く", "is_correct": false, "explanation": "後ろに否定がくる副詞で、ここには合わない。"}, {"text": "近く", "is_correct": false, "explanation": "場所や時の近さを表し、「近くして旅は終わった」は不自然。"}], "explanations": {"斯く": "「斯くして」で「このようにして」の意味になり、文が自然。", "高く": "形容詞の連用形で、「高くして旅が終わる」は意味が通らない。", "全く": "後ろに否定がくる副詞で、ここには合わない。", "近く": "場所や時の近さを表し、「近くして旅は終わった」は不自然。"}, "sentence_index": 0, "correct_answer": "斯く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このケーキは斯くおいしい。", "explanation": "「斯く」は様子を指し示す語で、程度の「とても」の意味では使えない。"}, {"text": "明日、斯く駅で会おう。", "explanation": "「斯く」は場所や時を表さず、意味が通らない。"}, {"text": "斯くが好きな色です。", "explanation": "「斯く」は副詞で、名詞のように「が」をつけて主語にできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '673c7278-d0aa-4d6c-8be5-a0511777716f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
