INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35887, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "斯く", "is_correct": true, "explanation": "正解。「かく」と読む。"}, {"text": "額", "is_correct": false, "explanation": "「がく」。一拍目が清音「か」と濁音「が」で違う。"}, {"text": "幕", "is_correct": false, "explanation": "「まく」。一拍目が「か」と「ま」で違う。"}, {"text": "紙", "is_correct": false, "explanation": "「かみ」。二拍目が「く」と「み」で違う。"}, {"text": "肩", "is_correct": false, "explanation": "「かた」。二拍目が「く」と「た」で違う。"}, {"text": "宅", "is_correct": false, "explanation": "「たく」。一拍目が「か」と「た」で違う。"}], "explanations": {"斯く": "正解。「かく」と読む。", "額": "「がく」。一拍目が清音「か」と濁音「が」で違う。", "幕": "「まく」。一拍目が「か」と「ま」で違う。", "紙": "「かみ」。二拍目が「く」と「み」で違う。", "肩": "「かた」。二拍目が「く」と「た」で違う。", "宅": "「たく」。一拍目が「か」と「た」で違う。"}, "sentence_index": null, "correct_answer": "斯く"}, "level_3": {"options": [{"text": "斯く", "is_correct": true, "explanation": "「このように書いてあった」という意味になり自然。"}, {"text": "決して", "is_correct": false, "explanation": "後ろに否定がくる副詞で、肯定文には入らない。"}, {"text": "少しも", "is_correct": false, "explanation": "否定と一緒に使う副詞で、この文には合わない。"}, {"text": "全然", "is_correct": false, "explanation": "否定と結びつく副詞で、この文では不自然。"}], "explanations": {"斯く": "「このように書いてあった」という意味になり自然。", "決して": "後ろに否定がくる副詞で、肯定文には入らない。", "少しも": "否定と一緒に使う副詞で、この文には合わない。", "全然": "否定と結びつく副詞で、この文では不自然。"}, "sentence_index": 6, "correct_answer": "斯く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "斯くの日はとても寒かった。", "explanation": "「斯く」は「このように」の意味で、「その日」のように時を指せない。"}, {"text": "斯くな人に会った。", "explanation": "「斯く」は副詞で、「な」をつけて名詞を修飾できない。"}, {"text": "机の上に斯くがある。", "explanation": "「斯く」は副詞で、物を表す名詞として使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '673c7278-d0aa-4d6c-8be5-a0511777716f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v