INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53509, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想い", "is_correct": true, "explanation": "正解。「おもい」と読む。"}, {"text": "多い", "is_correct": false, "explanation": "「おおい」。二拍目が「も」と「お」で違う。"}, {"text": "表", "is_correct": false, "explanation": "「おもて」。三拍目が「い」と「て」で違う。"}, {"text": "主に", "is_correct": false, "explanation": "「おもに」。三拍目が「い」と「に」で違う。"}, {"text": "重し", "is_correct": false, "explanation": "「おもし」。三拍目が「い」と「し」で違う。"}], "explanations": {"想い": "正解。「おもい」と読む。", "多い": "「おおい」。二拍目が「も」と「お」で違う。", "表": "「おもて」。三拍目が「い」と「て」で違う。", "主に": "「おもに」。三拍目が「い」と「に」で違う。", "重し": "「おもし」。三拍目が「い」と「し」で違う。"}, "sentence_index": null, "correct_answer": "想い"}, "level_3": {"options": [{"text": "想い", "is_correct": true, "explanation": "「君への想いを書く」で、気持ちを手紙に書くという意味になる。"}, {"text": "荷物", "is_correct": false, "explanation": "荷物は手紙に書く内容にならず、意味が通らない。"}, {"text": "切符", "is_correct": false, "explanation": "切符を手紙に書くことはできず不自然。"}, {"text": "料理", "is_correct": false, "explanation": "料理は書く内容ではなく、意味が合わない。"}], "explanations": {"想い": "「君への想いを書く」で、気持ちを手紙に書くという意味になる。", "荷物": "荷物は手紙に書く内容にならず、意味が通らない。", "切符": "切符を手紙に書くことはできず不自然。", "料理": "料理は書く内容ではなく、意味が合わない。"}, "sentence_index": 0, "correct_answer": "想い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "想いを自転車で運んだ。", "explanation": "「想い」は心の気持ちで、自転車で運ぶ物ではない。"}, {"text": "想いを冷蔵庫に入れた。", "explanation": "気持ちは物ではないので冷蔵庫に入れられない。"}, {"text": "想いが三キロ増えた。", "explanation": "気持ちは重さで量れず、体重の意味でも使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '673c7278-d0aa-4d6c-8be5-a0511777716f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
