INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53509, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "想い", "is_correct": true, "explanation": "正解。「おもい」と読む。"}, {"text": "お餅", "is_correct": false, "explanation": "「おもち」。三拍目が「い」と「ち」で違う。"}, {"text": "重さ", "is_correct": false, "explanation": "「おもさ」。三拍目が「い」と「さ」で違う。"}, {"text": "甥", "is_correct": false, "explanation": "「おい」。二拍目の「も」がない。"}, {"text": "思惑", "is_correct": false, "explanation": "「おもわく」。「おも」の後が「い」でなく「わく」。"}], "explanations": {"想い": "正解。「おもい」と読む。", "お餅": "「おもち」。三拍目が「い」と「ち」で違う。", "重さ": "「おもさ」。三拍目が「い」と「さ」で違う。", "甥": "「おい」。二拍目の「も」がない。", "思惑": "「おもわく」。「おも」の後が「い」でなく「わく」。"}, "sentence_index": null, "correct_answer": "想い"}, "level_3": {"options": [{"text": "想い", "is_correct": true, "explanation": "心の気持ちは言葉にしにくい、という自然な文になる。"}, {"text": "机", "is_correct": false, "explanation": "机は言葉にするものではなく意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "時計を言葉にしにくい、は意味が通らない。"}, {"text": "雨", "is_correct": false, "explanation": "雨を言葉にしにくい、は不自然。"}], "explanations": {"想い": "心の気持ちは言葉にしにくい、という自然な文になる。", "机": "机は言葉にするものではなく意味が通らない。", "時計": "時計を言葉にしにくい、は意味が通らない。", "雨": "雨を言葉にしにくい、は不自然。"}, "sentence_index": 6, "correct_answer": "想い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "想いで窓をふいた。", "explanation": "気持ちは道具ではないので、ふくことはできない。"}, {"text": "想いが雨で濡れた。", "explanation": "気持ちは物ではないので濡れない。"}, {"text": "駅まで想いに乗った。", "explanation": "「想い」は乗り物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '673c7278-d0aa-4d6c-8be5-a0511777716f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_