INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35974, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "残す", "is_correct": true, "explanation": "正しい見出し語の発音。"}, {"text": "伸ばす", "is_correct": false, "explanation": "のばす：二拍目が違う語。"}, {"text": "逃す", "is_correct": false, "explanation": "のがす：二拍目が違う語。"}, {"text": "隠す", "is_correct": false, "explanation": "かくす：最初の二拍が違う語。"}], "explanations": {"残す": "正しい見出し語の発音。", "伸ばす": "のばす：二拍目が違う語。", "逃す": "のがす：二拍目が違う語。", "隠す": "かくす：最初の二拍が違う語。"}, "sentence_index": null, "correct_answer": "残す"}, "level_3": {"options": [{"text": "残した", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "食べた", "is_correct": false, "explanation": "「全部食べずに半分食べた」は矛盾しない語に見えるが、ずに・半分と合わず不自然。"}, {"text": "歌った", "is_correct": false, "explanation": "半分歌ったは食べ物の文として意味をなさない。"}, {"text": "買った", "is_correct": false, "explanation": "食べずに買ったは前後がつながらない。"}], "explanations": {"残した": "文脈に合う正しい語。", "食べた": "「全部食べずに半分食べた」は矛盾しない語に見えるが、ずに・半分と合わず不自然。", "歌った": "半分歌ったは食べ物の文として意味をなさない。", "買った": "食べずに買ったは前後がつながらない。"}, "sentence_index": 6, "correct_answer": "残した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅まで残して行った。", "explanation": "「残す」は移動を表さない。"}, {"text": "花がきれいに残した。", "explanation": "物が主語なら「残った」。「残す」は他動詞。"}, {"text": "彼は早く残して走った。", "explanation": "様子や速さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80306a6e-bdc1-4f04-ade2-a16b1ad17ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
