INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35993, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "少しずつ続けて、結果がたまっていくこと。", "primary_collocate": null, "pronunciation": "つみかさね", "ipa": "tsɯmikasane", "syllable_count": 5, "sentences": [{"text": "毎日の積み重ねが大切だ。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "まいにち つみかさね たいせつ", "sentence_source": "generated"}, {"text": "練習の積み重ねで上手になった。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "れんしゅう つみかさね じょうず", "sentence_source": "generated"}, {"text": "小さな積み重ねを忘れないで。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "ちい つみかさね わす", "sentence_source": "generated"}, {"text": "努力の積み重ねが自信になる。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "どりょく つみかさね じしん", "sentence_source": "generated"}, {"text": "勉強は積み重ねだと思う。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "べんきょう つみかさね おも", "sentence_source": "generated"}, {"text": "積み重ねの力はすごい。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "つみかさね ちから", "sentence_source": "generated"}, {"text": "彼の成功は長い積み重ねの結果だ。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "かれ せいこう なが つみかさね けっか", "sentence_source": "generated"}, {"text": "積み重ねがないと続かない。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "つみかさね つづ", "sentence_source": "generated"}, {"text": "経験の積み重ねが役に立った。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "けいけん つみかさね やく た", "sentence_source": "generated"}, {"text": "日々の積み重ねを大事にしている。", "target_word": "積み重ね", "complexity_tier": "T3", "furigana": "ひび つみかさね だいじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "積み重ね", "label": "派生"}, {"form": "積み重ねる", "label": "派生"}, {"form": "積み重なる", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 努力などを少しずつ重ねること", "collocate_grounding": {"status": "no_sour