INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36006, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "録音や録画した音や映像を、もう一度流すこと。", "primary_collocate": null, "pronunciation": "さいせい", "ipa": "saiseː", "syllable_count": 4, "sentences": [{"text": "動画の再生が止まった。", "target_word": "再生", "complexity_tier": "T3", "furigana": "どうが さいせい と", "sentence_source": "generated"}, {"text": "この曲を再生してください。", "target_word": "再生", "complexity_tier": "T3", "furigana": "きょく さいせい", "sentence_source": "generated"}, {"text": "再生ボタンを押して。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせい お", "sentence_source": "generated"}, {"text": "録音を再生して聞いてみた。", "target_word": "再生", "complexity_tier": "T3", "furigana": "ろくおん さいせい き", "sentence_source": "generated"}, {"text": "その動画は再生回数が多い。", "target_word": "再生", "complexity_tier": "T3", "furigana": "どうが さいせい かいすう おお", "sentence_source": "generated"}, {"text": "スマホで音楽を再生している。", "target_word": "再生", "complexity_tier": "T3", "furigana": "おんがく さいせい", "sentence_source": "generated"}, {"text": "再生がうまくいかない。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせい", "sentence_source": "generated"}, {"text": "もう一度最初から再生しよう。", "target_word": "再生", "complexity_tier": "T3", "furigana": "いちど さいしょ さいせい", "sentence_source": "generated"}, {"text": "再生中に電話が鳴った。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせいちゅう でんわ な", "sentence_source": "generated"}, {"text": "古いテープは再生できない。", "target_word": "再生", "complexity_tier": "T3", "furigana": "ふる さいせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生する", "label": "派生"}, {"form": "再生した", "label": "活用"}, {"form": "再生ボタン", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 録音・録画を流すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-