INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35993, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "積み重ね", "is_correct": true, "explanation": "正解。聞こえた語そのもの。"}, {"text": "摘み草", "is_correct": false, "explanation": "つみくさ。「つみ」は同じだが後半が異なる。一モーラ差の実在語が見つからないための近音語。"}, {"text": "積み木", "is_correct": false, "explanation": "つみき。前半「つみ」が同じで、後半が短い近音語。"}, {"text": "罪深さ", "is_correct": false, "explanation": "つみぶかさ。「つみ」と「かさ」に似た音を含む実在語。"}], "explanations": {"積み重ね": "正解。聞こえた語そのもの。", "摘み草": "つみくさ。「つみ」は同じだが後半が異なる。一モーラ差の実在語が見つからないための近音語。", "積み木": "つみき。前半「つみ」が同じで、後半が短い近音語。", "罪深さ": "つみぶかさ。「つみ」と「かさ」に似た音を含む実在語。"}, "sentence_index": null, "correct_answer": "積み重ね"}, "level_3": {"options": [{"text": "積み重ね", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "天井", "is_correct": false, "explanation": "意味：「毎日の天井が大切だ」は意味が通らない。"}, {"text": "雨", "is_correct": false, "explanation": "意味：「毎日の雨が大切だ」は意味が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "連語：「毎日の値段」は結びつきが不自然。"}], "explanations": {"積み重ね": "正解。文の意味に合う。", "天井": "意味：「毎日の天井が大切だ」は意味が通らない。", "雨": "意味：「毎日の雨が大切だ」は意味が通らない。", "値段": "連語：「毎日の値段」は結びつきが不自然。"}, "sentence_index": 0, "correct_answer": "積み重ね"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "努力の積み重ねが三冊自信になる。", "explanation": "助数詞の誤り：抽象的な積み重ねを冊で数えることはできない。"}, {"text": "努力を積み重ねが自信になる。", "explanation": "助詞の混同：「努力の積み重ね」とすべき。"}, {"text": "積み重ねが自信に昨日なる。", "explanation": "語順の誤り：時の副詞の位置が不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84a90019-3bc3-4169-be4a-ea14fe767bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
