INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36082, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "創造", "is_correct": true, "explanation": "正解。聞こえた語そのもの。"}, {"text": "相続", "is_correct": false, "explanation": "そうぞく。最後のモーラ「う」が「く」に変わる。"}, {"text": "騒動", "is_correct": false, "explanation": "そうどう。三つ目のモーラ「ぞ」が「ど」に変わる。"}, {"text": "構造", "is_correct": false, "explanation": "こうぞう。最初のモーラ「そ」が「こ」に変わる。"}, {"text": "総合", "is_correct": false, "explanation": "そうごう。三つ目のモーラ「ぞ」が「ご」に変わる。"}], "explanations": {"創造": "正解。聞こえた語そのもの。", "相続": "そうぞく。最後のモーラ「う」が「く」に変わる。", "騒動": "そうどう。三つ目のモーラ「ぞ」が「ど」に変わる。", "構造": "こうぞう。最初のモーラ「そ」が「こ」に変わる。", "総合": "そうごう。三つ目のモーラ「ぞ」が「ご」に変わる。"}, "sentence_index": null, "correct_answer": "創造"}, "level_3": {"options": [{"text": "創造", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "台所", "is_correct": false, "explanation": "意味：「芸術は台所の世界だ」は意味が通らない。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：「芸術は睡眠の世界だ」は意味が通らない。"}, {"text": "渋滞", "is_correct": false, "explanation": "連語：「芸術は渋滞の世界だ」は不自然。"}], "explanations": {"創造": "正解。文の意味に合う。", "台所": "意味：「芸術は台所の世界だ」は意味が通らない。", "睡眠": "意味：「芸術は睡眠の世界だ」は意味が通らない。", "渋滞": "連語：「芸術は渋滞の世界だ」は不自然。"}, "sentence_index": 0, "correct_answer": "創造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は創造する喜びを三本知った。", "explanation": "助数詞の誤り：喜びは本で数えない。"}, {"text": "彼に創造する喜びを知った。", "explanation": "助詞の混同：主語は「は／が」で示す。"}, {"text": "彼は創造する喜びを知っている昨日。", "explanation": "語順の誤り：時の副詞が文末にあり不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84a90019-3bc3-4169-be4a-ea14fe767bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generati