INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36150, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "前にいた人が持っていたものを、あとから来た人がもらうこと。", "primary_collocate": null, "pronunciation": "けいしょう", "ipa": "ke̞ːɕoː", "syllable_count": 4, "sentences": [{"text": "父の店の継承が決まった。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "王位の継承は大きな問題だった。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "兄が家業を継承することになった。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "土地の継承について家族で話した。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "継承の手続きに時間がかかった。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "彼は祖父の名前を継承した。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "財産の継承でもめる家もある。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "会社の継承はまだ決まっていない。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "その権利の継承が認められた。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "姉が母の店を継承している。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "継承する", "label": "派生"}, {"form": "継承した", "label": "活用"}, {"form": "継承者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 前の人の持ち物や地位を受け継ぐこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859046b3-9261-4cf5-ab78-05ffebb00d54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36151, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "先代から受け継いで、次の世代に伝えること。特に、文化や技術、権利などを引き継ぐこと。", "primary_collocate": null, "pronunciation": "けいしょう", "ipa": "ke̞ːɕoː", "syllable_count": 4, "sentences": [{"text": "伝統の継承はとても大切だ。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "祭りを子どもたちに継承したい。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "技術の継承が難しくなっている。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "この町では文化の継承が進んでいる。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "若い人が伝統を継承している。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "継承のために教室が開かれた。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "昔の歌を次の世代に継承する。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "職人の技の継承が問題になっている。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "言葉の継承には時間がかかる。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}, {"text": "祖母から料理を継承した。", "target_word": "継承", "complexity_tier": "T3", "furigana": "けいしょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "継承する", "label": "派生"}, {"form": "継承される", "label": "活用"}, {"form": "継承者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 文化や技術を次の世代へ伝えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859046b3-9261-4cf5-ab78-05ffebb00d54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36168, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が何かをする相手や、目を向けるもの。", "primary_collocate": null, "pronunciation": "たいしょう", "ipa": "taiɕoː", "syllable_count": 4, "sentences": [{"text": "この本は子どもが対象です。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "調査の対象は中学生だった。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "この割引は学生を対象にしている。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "彼女はみんなの注目の対象だ。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "対象になる人に手紙を送った。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "大人は今回の対象ではない。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "研究の対象を決めるのは難しい。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "この大会は全員が対象だ。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "対象を広げて調べてみよう。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "鳥が写真の対象になった。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "対象者", "label": "派生"}, {"form": "対象外", "label": "派生"}, {"form": "対象物", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 何かをする相手や向けられる人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859046b3-9261-4cf5-ab78-05ffebb00d54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36169, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "行動や考えの向かう先となるものや人。", "primary_collocate": null, "pronunciation": "たいしょう", "ipa": "taiɕoː", "syllable_count": 4, "sentences": [{"text": "星は兄の興味の対象だ。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "批判の対象になるのはつらい。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "対象をよく見て絵を描こう。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "その町は観光の対象として人気だ。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "心配の対象は弟のことだった。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "この問題は話し合いの対象だ。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "研究の対象として虫を選んだ。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "彼の父は尊敬の対象になった。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "対象がはっきりすると考えやすい。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}, {"text": "花はよく写真の対象になる。", "target_word": "対象", "complexity_tier": "T3", "furigana": "たいしょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "対象者", "label": "派生"}, {"form": "対象外", "label": "派生"}, {"form": "対象物", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 行動や考えが向かう先のもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859046b3-9261-4cf5-ab78-05ffebb00d54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36107, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "古典", "is_correct": true, "explanation": "正解：「古典」（こてん）。"}, {"text": "御殿", "is_correct": false, "explanation": "「御殿」はごてんと読み、最初のモーラ「こ」が「ご」になる清濁の違い。"}, {"text": "固定", "is_correct": false, "explanation": "「固定」はこていと読み、最後のモーラ「ん」が「い」に変わる一モーラ差。"}, {"text": "好転", "is_correct": false, "explanation": "「好転」はこうてんと読み、「こ」が「こう」と長くなる長短の違い。"}, {"text": "沽券", "is_correct": false, "explanation": "「沽券」はこけんと読み、二番目のモーラ「て」が「け」に変わる一モーラ差。"}], "explanations": {"古典": "正解：「古典」（こてん）。", "御殿": "「御殿」はごてんと読み、最初のモーラ「こ」が「ご」になる清濁の違い。", "固定": "「固定」はこていと読み、最後のモーラ「ん」が「い」に変わる一モーラ差。", "好転": "「好転」はこうてんと読み、「こ」が「こう」と長くなる長短の違い。", "沽券": "「沽券」はこけんと読み、二番目のモーラ「て」が「け」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "古典"}, "level_3": {"options": [{"text": "古典", "is_correct": true, "explanation": "正解：この文の意味に合う。"}, {"text": "食事", "is_correct": false, "explanation": "意味：食事は読むものではない。"}, {"text": "運動", "is_correct": false, "explanation": "意味：運動は読むことができない。"}, {"text": "天気", "is_correct": false, "explanation": "連語：「天気を読む」は空模様を予想する意味で、国語の時間に合わない。"}], "explanations": {"古典": "正解：この文の意味に合う。", "食事": "意味：食事は読むものではない。", "運動": "意味：運動は読むことができない。", "天気": "連語：「天気を読む」は空模様を予想する意味で、国語の時間に合わない。"}, "sentence_index": 0, "correct_answer": "古典"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この古典は昨日書かれたばかりだ。", "explanation": "古典は長く愛されてきた作品で、昨日書かれたものではない。"}, {"text": "古典を三杯飲みました。", "explanation": "古典は飲み物ではなく、助数詞「杯」も合わない。"}, {"text": "古典で家まで走って帰った。", "explanation": "古典は作品であり、移動の手段にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a71e33e0-ad94-4c2a-bdbb-4ac4f21e44da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
