INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36202, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "数のあとにつけて、時刻を表すことば。", "primary_collocate": null, "pronunciation": "じ", "ipa": "dʑi", "syllable_count": 1, "sentences": [{"text": "毎朝七時に起きます。", "target_word": "時", "complexity_tier": "T3", "furigana": "まいあさ しち じ お", "sentence_source": "generated"}, {"text": "今、三時です。", "target_word": "時", "complexity_tier": "T3", "furigana": "いま さん じ", "sentence_source": "generated"}, {"text": "授業は九時に始まる。", "target_word": "時", "complexity_tier": "T3", "furigana": "じゅぎょう く じ はじ", "sentence_source": "generated"}, {"text": "五時に駅で会おう。", "target_word": "時", "complexity_tier": "T3", "furigana": "ご じ えき あ", "sentence_source": "generated"}, {"text": "店は十時まで開いている。", "target_word": "時", "complexity_tier": "T3", "furigana": "みせ じゅう じ あ", "sentence_source": "generated"}, {"text": "夜十一時に寝た。", "target_word": "時", "complexity_tier": "T3", "furigana": "よる じゅういち じ ね", "sentence_source": "generated"}, {"text": "会議は二時からです。", "target_word": "時", "complexity_tier": "T3", "furigana": "かいぎ に じ", "sentence_source": "generated"}, {"text": "六時のバスに乗った。", "target_word": "時", "complexity_tier": "T3", "furigana": "ろく じ の", "sentence_source": "generated"}, {"text": "昼の十二時に食べる。", "target_word": "時", "complexity_tier": "T3", "furigana": "ひる じゅうに じ た", "sentence_source": "generated"}, {"text": "八時になったら出かけよう。", "target_word": "時", "complexity_tier": "T3", "furigana": "はち じ で", "sentence_source": "generated"}], "morphological_forms": [{"form": "時間", "label": "派生"}, {"form": "時刻", "label": "派生"}, {"form": "何時", "label": "派生"}], "register": "plain", "sense_fingerprint": "接尾辞 | 数につけて時刻を表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9af3a48-60d8-4d8a-963