INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36220, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "知識や技術を学ぶこと。", "primary_collocate": null, "pronunciation": "べんきょう", "ipa": "beŋkʲoː", "syllable_count": 4, "sentences": [{"text": "毎日英語を勉強している。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "まいにち えいご べんきょう", "sentence_source": "generated"}, {"text": "勉強は楽しい。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "べんきょう たの", "sentence_source": "generated"}, {"text": "図書館で勉強しよう。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "としょかん べんきょう", "sentence_source": "generated"}, {"text": "テストの勉強が終わった。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "べんきょう お", "sentence_source": "generated"}, {"text": "兄は勉強が好きだ。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "あに べんきょう す", "sentence_source": "generated"}, {"text": "夜遅くまで勉強した。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "よる おそ べんきょう", "sentence_source": "generated"}, {"text": "勉強の時間を増やす。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "べんきょう じかん ふ", "sentence_source": "generated"}, {"text": "友だちと一緒に勉強する。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "とも いっしょ べんきょう", "sentence_source": "generated"}, {"text": "数学の勉強は難しい。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "すうがく べんきょう むずか", "sentence_source": "generated"}, {"text": "勉強して、医者になりたい。", "target_word": "勉強", "complexity_tier": "T3", "furigana": "べんきょう いしゃ", "sentence_source": "generated"}], "morphological_forms": [{"form": "勉強する", "label": "派生"}, {"form": "勉強した", "label": "活用"}, {"form": "勉強して", "label": "活用"}, {"form": "勉強家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 知識や技術を学ぶこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'c