INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36180, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新た", "is_correct": true, "explanation": "聞こえた音と同じ語です。"}, {"text": "嵐", "is_correct": false, "explanation": "あらし：最後の「た」が「し」に変わる一モーラ差。"}, {"text": "明日", "is_correct": false, "explanation": "あした：二番目の「ら」が「し」に変わる一モーラ差。"}, {"text": "洗う", "is_correct": false, "explanation": "あらう：最後の「た」が「う」に変わる一モーラ差。"}, {"text": "数多", "is_correct": false, "explanation": "あまた：二番目の「ら」が「ま」に変わる一モーラ差。"}], "explanations": {"新た": "聞こえた音と同じ語です。", "嵐": "あらし：最後の「た」が「し」に変わる一モーラ差。", "明日": "あした：二番目の「ら」が「し」に変わる一モーラ差。", "洗う": "あらう：最後の「た」が「う」に変わる一モーラ差。", "数多": "あまた：二番目の「ら」が「ま」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "新た"}, "level_3": {"options": [{"text": "新た", "is_correct": true, "explanation": "文の意味に合う正しい語です。"}, {"text": "静か", "is_correct": false, "explanation": "「静かな目標」は意味が合わない。"}, {"text": "丈夫", "is_correct": false, "explanation": "目標が丈夫というのは不自然。"}, {"text": "親切", "is_correct": false, "explanation": "目標が親切というのは意味が通らない。"}], "explanations": {"新た": "文の意味に合う正しい語です。", "静か": "「静かな目標」は意味が合わない。", "丈夫": "目標が丈夫というのは不自然。", "親切": "目標が親切というのは意味が通らない。"}, "sentence_index": 0, "correct_answer": "新た"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新たな服はもう十年着ている。", "explanation": "十年着た服は新しくないので矛盾している。"}, {"text": "祖父の家は新たで古い。", "explanation": "「新た」と「古い」が同時に成り立たない。"}, {"text": "昨日の新たなパンは固くなった。", "explanation": "「新た」は物の鮮度ではなく、今までにないことを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9bbaaec-6e6d-42ca-be9f-8456b30a019d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36180, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新たが目標を立てました。", "corrected_sentence": "新たな目標を立てました。", "error_description": "名詞を修飾するときは「新たな」の形にする。「新たが」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "新た", "is_correct": true, "explanation": "語幹「新た」に「に」が付いて動詞を修飾する。"}, {"text": "新たな", "is_correct": false, "explanation": "後ろに「に」が続くので「な」形は入らない。"}, {"text": "新ただ", "is_correct": false, "explanation": "「だ」は文末の形で、ここでは使えない。"}, {"text": "新たで", "is_correct": false, "explanation": "「で」の形では「できた」を修飾できない。"}], "correct_form": "新た", "base_form": "新た", "form_label": "活用", "sentence_index": 1, "explanations": {"新た": "語幹「新た」に「に」が付いて動詞を修飾する。", "新たな": "後ろに「に」が続くので「な」形は入らない。", "新ただ": "「だ」は文末の形で、ここでは使えない。", "新たで": "「で」の形では「できた」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9bbaaec-6e6d-42ca-be9f-8456b30a019d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
