INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35621, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "国や地域をこえて、世界全体に広がっているさま。", "primary_collocate": null, "pronunciation": "ぐろーばる", "ipa": "ɡɯɾoːbaɾɯ", "syllable_count": 5, "sentences": [{"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "グローバルな", "complexity_tier": "T6", "furigana": "ぐろーばる きんゆう しじょう しゃかい けいざいてき ぶんみゃく こべつ きぎょう とうしか しゅたい きょくしょてき いしけってい けっして たんじゅん せんけい とらえ", "sentence_source": "mined"}, {"text": "この憧れの感情は、やがてグローバルな大衆向けブランドによって巧妙に咀嚼され、誰もが手が届く価格帯へと昇華されるのだ。", "target_word": "グローバルな", "complexity_tier": "T6", "furigana": "あこがれ かんじょう たいしゅうむけ こうみょう そしゃく だれ て とどく かかくたい しょうか", "sentence_source": "mined"}, {"text": "世界はグローバルだ。", "target_word": "グローバル", "complexity_tier": "T1", "furigana": "せかい", "sentence_source": "generated"}, {"text": "この会社はグローバルです。", "target_word": "グローバル", "complexity_tier": "T2", "furigana": "かいしゃ", "sentence_source": "generated"}, {"text": "グローバルな問題を学びました。", "target_word": "グローバルな", "complexity_tier": "T2", "furigana": "もんだい まなび", "sentence_source": "generated"}, {"text": "グローバルに活動している企業が増えている。", "target_word": "グローバルに", "complexity_tier": "T3", "furigana": "かつどう きぎょう ふえて", "sentence_source": "generated"}, {"text": "世界でグローバルに売れる商品を作りたい。", "target_word": "グローバルに", "complexity_tier": "T3", "furigana": "せかい うれる しょうひん つくり", "sentence_source": "generated"}, {"text": "グローバルな変化が起きれば、地方の生活も変わる。", "target_word": "グローバルな", "complexity_tier": "T4", "furigana": "へんか おきれば ちほう せいかつ かわる", "sentence_source": "generated"}, {"text": "とてもグローバルで、世界中に支店がある会社だ。", "target_word": "グローバルで", "complexity_tier": "T4", "furigana": "せかいじゅう してん かいしゃ", "sentence_source": "generated"}, {"text": "つながりがグローバルになるにつれて、国どうしの競争も激しくなってきた。", "target_word": "グローバルに", "complexity_tier": "T5", "furigana": "くに きょうそう はげしく", "sentence_source": "generated"}], "morphological_forms": [{"form": "グローバルな", "label": "活用"}, {"form": "グローバルに", "label": "活用"}, {"form": "グローバルだ", "label": "活用"}, {"form": "グローバル化", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 世界全体に広がっているさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): サプライ (Zipf 3.19), ミクロ (Zipf 3.34), 局所 (Zipf 3.35), 線形 (Zipf 2.97)']::text[], 'b7d4c905-0266-40e0-97e9-98715a34a555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35620, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "世界中につながっていること。", "primary_collocate": null, "pronunciation": "ぐろーばる", "ipa": "ɡɯɾoːbaɾɯ", "syllable_count": 5, "sentences": [{"text": "音楽はグローバルだ。", "target_word": "グローバル", "complexity_tier": "T1", "furigana": "おんがく", "sentence_source": "generated"}, {"text": "グローバルな世界だ。", "target_word": "グローバルな", "complexity_tier": "T1", "furigana": "せかい", "sentence_source": "generated"}, {"text": "ネットはグローバルです。", "target_word": "グローバル", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "グローバルな仲間が増えました。", "target_word": "グローバルな", "complexity_tier": "T2", "furigana": "なかま ふえ", "sentence_source": "generated"}, {"text": "世界中がグローバルにつながっている。", "target_word": "グローバルに", "complexity_tier": "T3", "furigana": "せかいじゅう", "sentence_source": "generated"}, {"text": "スマホでグローバルに連絡できる。", "target_word": "グローバルに", "complexity_tier": "T3", "furigana": "れんらく", "sentence_source": "generated"}, {"text": "グローバルになれば、小さな店も世界に知られる。", "target_word": "グローバルに", "complexity_tier": "T4", "furigana": "ちい みせ せかい しられる", "sentence_source": "generated"}, {"text": "学生にグローバルな経験をさせたい。", "target_word": "グローバルな", "complexity_tier": "T4", "furigana": "がくせい けいけん", "sentence_source": "generated"}, {"text": "インターネットの普及によって、人々の暮らしはますますグローバルになった。", "target_word": "グローバルに", "complexity_tier": "T5", "furigana": "ふきゅう ひとびと くらし", "sentence_source": "generated"}, {"text": "グローバルで、誰とでもつながれる社会だ。", "target_word": "グローバルで", "complexity_tier": "T3", "furigana": "だれ しゃかい", "sentence_source": "generated"}], "morphological_forms": [{"form": "グローバルな", "label": "活用"}, {"form": "グローバルに", "label": "活用"}, {"form": "グローバルだ", "label": "活用"}, {"form": "グローバル化", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 世界中につながっていること", "collocate_grounding": {"status": "n