INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53418, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事についてこころでかんがえ、気にすること。主に『意に介さない』という形で、『気にしない』という意味で使われます。", "primary_collocate": null, "pronunciation": "かいす", "ipa": "kaisɯ", "syllable_count": 3, "sentences": [{"text": "厳冬の冷たさなど意に介さず、ただ純粋に外で遊ぶための準備に余念がないのだ。", "target_word": "介さず", "complexity_tier": "T6", "furigana": "げんとう つめたさ い かい じゅんすい そと あそぶ じゅんび よねん", "sentence_source": "mined"}, {"text": "意に介さない。", "target_word": "介さない", "complexity_tier": "T1", "furigana": "い かい", "sentence_source": "generated"}, {"text": "彼は批判を意に介しません。", "target_word": "介しません", "complexity_tier": "T2", "furigana": "かれ ひはん い かい", "sentence_source": "generated"}, {"text": "彼女は雨を意に介しませんでした。", "target_word": "介しませんでした", "complexity_tier": "T2", "furigana": "かのじょ あめ い かい", "sentence_source": "generated"}, {"text": "周りの目を意に介さずに、自分の道を進んでいる。", "target_word": "介さずに", "complexity_tier": "T4", "furigana": "まわり め い かい じぶん みち すすんで", "sentence_source": "generated"}, {"text": "彼は人の噂を意に介さなくて、いつも平気だ。", "target_word": "介さなくて", "complexity_tier": "T3", "furigana": "かれ ひと うわさ い かい へいき", "sentence_source": "generated"}, {"text": "悪口を言われても意に介さない人は強い。", "target_word": "介さない", "complexity_tier": "T4", "furigana": "わるぐち い い かい ひと つよい", "sentence_source": "generated"}, {"text": "もし失敗を意に介さなければ、もっと挑戦できるのに。", "target_word": "介さなければ", "complexity_tier": "T4", "furigana": "しっぱい い かい ちょうせん", "sentence_source": "generated"}, {"text": "先生に注意されても、彼は意に介さなかった。", "target_word": "介さなかった", "complexity_tier": "T4", "furigana": "せんせい ちゅうい かれ い かい", "sentence_source": "generated"}, {"text": "周囲の冷ややかな視線を意に介さず、彼は黙々と練習を続けた。", "target_word": "介さず", "complexity_tier": "T5", "furigana": "しゅうい ひややか しせん い かい かれ もくもく れんしゅう つづけた", "sentence_source": "generated"}], "morphological_forms": [{"form": "介さない", "label": "活用"}, {"form": "介さず", "label": "活用"}, {"form": "介さなければ", "label": "活用"}, {"form": "介しません", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 意に介さず気にしないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d4c905-0266-40e0-97e9-98715a34a555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53417, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "こころでかんがえて、きにするということです。", "primary_collocate": null, "pronunciation": "かいす", "ipa": "kaisɯ", "syllable_count": 3, "sentences": [{"text": "意に介さず行く。", "target_word": "介さず", "complexity_tier": "T1", "furigana": "い かい いく", "sentence_source": "generated"}, {"text": "彼は意に介さない。", "target_word": "介さない", "complexity_tier": "T1", "furigana": "かれ い かい", "sentence_source": "generated"}, {"text": "私は悪口を意に介しません。", "target_word": "介しません", "complexity_tier": "T2", "furigana": "わたし わるぐち い かい", "sentence_source": "generated"}, {"text": "弟は寒さを意に介しませんでした。", "target_word": "介しませんでした", "complexity_tier": "T2", "furigana": "おとうと さむさ い かい", "sentence_source": "generated"}, {"text": "人の目を意に介さずに歩いている。", "target_word": "介さずに", "complexity_tier": "T3", "furigana": "ひと め い かい あるいて", "sentence_source": "generated"}, {"text": "細かいことを意に介さないでいたい。", "target_word": "介さないで", "complexity_tier": "T3", "furigana": "こまかい い かい", "sentence_source": "generated"}, {"text": "人に何を言われても、彼女は意に介さない。", "target_word": "介さない", "complexity_tier": "T4", "furigana": "ひと なに い かのじょ い かい", "sentence_source": "generated"}, {"text": "意に介さなければ、うまくいくこともある。", "target_word": "介さなければ", "complexity_tier": "T4", "furigana": "い かい", "sentence_source": "generated"}, {"text": "親に叱られても意に介さない子どもが心配だ。", "target_word": "介さない", "complexity_tier": "T4", "furigana": "おや しかられて い かい こども しんぱい", "sentence_source": "generated"}, {"text": "どんなに周りが騒いでも、彼は意に介さずに自分の仕事を続けていた。", "target_word": "介さずに", "complexity_tier": "T5", "furigana": "まわり さわいで かれ い かい じぶん しごと つづけて", "sentence_source": "generated"}], "morphological_forms": [{"form": "介さない", "label": "活用"}, {"form": "介さず", "label": "活用"}, {"form": "介さなければ", "label": "活用"}, {"form": "介しません", "label": "活用"}], "register": "plain", "sense_fingerprint