INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36601, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "理由や目的を尋ねる時に使う言葉で、「なぜ」と同じ意味です。原因や事情を問う時に用います。", "primary_collocate": null, "pronunciation": "なぜ", "ipa": "naze", "syllable_count": 2, "sentences": [{"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "なぜ", "complexity_tier": "T6", "furigana": "むすう しゅたい かぎられた じょうほう もとづき たえず てきおう くりかえす かてい いと とっぱつてき けんげん ほか", "sentence_source": "mined"}, {"text": "誰が、どこで、何を、なぜ、どのように書くか、その技法が進化します。", "target_word": "なぜ", "complexity_tier": "T6", "furigana": "だれ なに かく ぎほう しんか", "sentence_source": "mined"}, {"text": "何故だろう。", "target_word": "何故", "complexity_tier": "T1", "furigana": "なぜ", "sentence_source": "generated"}, {"text": "なぜ学校を休みましたか。", "target_word": "なぜ", "complexity_tier": "T2", "furigana": "がっこう やすみ", "sentence_source": "generated"}, {"text": "今日はなぜ早く帰りましたか。", "target_word": "なぜ", "complexity_tier": "T2", "furigana": "きょう はやく かえり", "sentence_source": "generated"}, {"text": "彼がなぜ怒っているのか、私にはわからない。", "target_word": "なぜ", "complexity_tier": "T3", "furigana": "かれ おこって わたし", "sentence_source": "generated"}, {"text": "何故こんなに高いのか、店の人に聞いてみた。", "target_word": "何故", "complexity_tier": "T3", "furigana": "なぜ たかい みせ ひと きいて", "sentence_source": "generated"}, {"text": "なぜ約束を守らなかったのかと、先生に聞かれた。", "target_word": "なぜ", "complexity_tier": "T4", "furigana": "やくそく まもらなかった せんせい きかれ", "sentence_source": "generated"}, {"text": "失敗したのはなぜかを考えれば、次はうまくいくはずだ。", "target_word": "なぜ", "complexity_tier": "T4", "furigana": "しっぱい かんがえれば つぎ", "sentence_source": "generated"}, {"text": "私が知りたいのは、彼がなぜ突然仕事をやめてしまったのかということだ。", "target_word": "なぜ", "complexity_tier": "T5", "furigana": "わたし しりたい かれ とつぜん しごと", "sentence_source": "generated"}], "morphological_forms": [{"form": "なぜなら", "label": "派生"}, {"form": "なぜか", "label": "派生"}, {"form": "なぜならば", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | 理由を問う疑問の副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 絶えず (Zipf 3.47), イノベーション (Zipf 3.6), 突発 (Zipf 3.44), 顕現 (Zipf 2.9)']::text[], 'b7d4c905-0266-40e0-97e9-98715a34a555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36600, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "どうして、という意味の言葉です。", "primary_collocate": null, "pronunciation": "なぜ", "ipa": "naze", "syllable_count": 2, "sentences": [{"text": "なぜ行くの？", "target_word": "なぜ", "complexity_tier": "T1", "furigana": "いく", "sentence_source": "generated"}, {"text": "なぜだろう。", "target_word": "なぜ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "なぜ遅れましたか。", "target_word": "なぜ", "complexity_tier": "T2", "furigana": "おくれ", "sentence_source": "generated"}, {"text": "海はなぜ青いですか。", "target_word": "なぜ", "complexity_tier": "T2", "furigana": "うみ あおい", "sentence_source": "generated"}, {"text": "あの人はなぜ毎日走るのですか。", "target_word": "なぜ", "complexity_tier": "T2", "furigana": "ひと まいにち はしる", "sentence_source": "generated"}, {"text": "彼はなぜ泣いているのか、教えてください。", "target_word": "なぜ", "complexity_tier": "T3", "furigana": "かれ ないて おしえて", "sentence_source": "generated"}, {"text": "「なぜ？」と聞かれて、答えられなかった。", "target_word": "なぜ", "complexity_tier": "T4", "furigana": "きかれて こたえられなかった", "sentence_source": "generated"}, {"text": "なぜ勉強しなければならないのかと、子どもに聞かれた。", "target_word": "なぜ", "complexity_tier": "T4", "furigana": "べんきょう こども きかれ", "sentence_source": "generated"}, {"text": "雨がなぜ急に降ったのか、天気予報を見ればわかる。", "target_word": "なぜ", "complexity_tier": "T4", "furigana": "あめ きゅう ふった てんきよほう みれば", "sentence_source": "generated"}, {"text": "友達がなぜ急に引っ越すことになったのか、私は最後までわからなかった。", "target_word": "なぜ", "complexity_tier": "T5", "furigana": "ともだち きゅう ひっこす わたし さいご", "sentence_source": "generated"}], "morphological_forms": [{"form": "なぜなら", "label": "派生"}, {"form": "なぜか", "label": "派生"}, {"form": "なぜならば", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | どうして、と問う言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}