INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52354, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "地球の表面や地下にある岩石や土の性質や構造のこと。", "primary_collocate": null, "pronunciation": "ちしつ", "ipa": "t͡ɕiɕitsɯ", "syllable_count": 3, "sentences": [{"text": "地球システムにおける炭素循環は、地質学的時間軸において精緻な均衡を保ってきた。", "target_word": "地質", "complexity_tier": "T6", "furigana": "ちきゅう たんそ じゅんかん ちしつがくてき じかんじく せいち きんこう たもって", "sentence_source": "mined"}, {"text": "ワインという液体媒体において、テロワールは単なる気象・地質学的変数の集合体ではなく、地質学的記憶が液相内に結晶化した記号系として機能する。", "target_word": "地質", "complexity_tier": "T6", "furigana": "えきたい ばいたい たんなる きしょう ちしつがくてき へんすう しゅうごうたい ちしつがくてき きおく えきそうない けっしょうか きごうけい きのう", "sentence_source": "mined"}, {"text": "地質を調べる。", "target_word": "地質", "complexity_tier": "T1", "furigana": "ちしつ しらべる", "sentence_source": "generated"}, {"text": "ここの地質はかたいです。", "target_word": "地質", "complexity_tier": "T2", "furigana": "ちしつ", "sentence_source": "generated"}, {"text": "地質の調査に行きました。", "target_word": "地質", "complexity_tier": "T2", "furigana": "ちしつ ちょうさ いき", "sentence_source": "generated"}, {"text": "この地域の地質を調べている研究者がいる。", "target_word": "地質", "complexity_tier": "T3", "furigana": "ちいき ちしつ しらべて けんきゅうしゃ", "sentence_source": "generated"}, {"text": "地質が違うため、同じ作物は育てられない。", "target_word": "地質", "complexity_tier": "T3", "furigana": "ちしつ ちがう おなじ さくもつ そだてられない", "sentence_source": "generated"}, {"text": "地質が変われば、そこに生える植物も変わる。", "target_word": "地質", "complexity_tier": "T4", "furigana": "ちしつ かわれば はえる しょくぶつ かわる", "sentence_source": "generated"}, {"text": "この島の地質は、火山活動によって形づくられた。", "target_word": "地質", "complexity_tier": "T4", "furigana": "しま ちしつ かざんかつどう かたちづくられた", "sentence_source": "generated"}, {"text": "ダムを建設する前に、その土地の地質を詳しく調べておく必要がある。", "target_word": "地質", "complexity_tier": "T5", "furigana": "けんせつ まえ とち ちしつ くわしく しらべて ひつよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "地質学", "label": "派生"}, {"form": "地質調査", "label": "派生"}, {"form": "地質時代", "label": "派生"}, {"form": "地質学者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 岩石や土の性質と構造", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d4c905-0266-40e0-97e9-98715a34a555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52353, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "地面の石や土のようすのこと。", "primary_collocate": null, "pronunciation": "ちしつ", "ipa": "t͡ɕiɕitsɯ", "syllable_count": 3, "sentences": [{"text": "地質は大切だ。", "target_word": "地質", "complexity_tier": "T1", "furigana": "ちしつ たいせつ", "sentence_source": "generated"}, {"text": "地質が違う。", "target_word": "地質", "complexity_tier": "T1", "furigana": "ちしつ ちがう", "sentence_source": "generated"}, {"text": "この山の地質は古いです。", "target_word": "地質", "complexity_tier": "T2", "furigana": "やま ちしつ ふるい", "sentence_source": "generated"}, {"text": "地質を勉強しました。", "target_word": "地質", "complexity_tier": "T2", "furigana": "ちしつ べんきょう", "sentence_source": "generated"}, {"text": "川の近くの地質はやわらかいです。", "target_word": "地質", "complexity_tier": "T2", "furigana": "かわ ちかく ちしつ", "sentence_source": "generated"}, {"text": "地質を調べて、家を建てる場所を決めた。", "target_word": "地質", "complexity_tier": "T3", "furigana": "ちしつ しらべて いえ たてる ばしょ きめた", "sentence_source": "generated"}, {"text": "地質について学べる博物館に行きたい。", "target_word": "地質", "complexity_tier": "T3", "furigana": "ちしつ まなべる はくぶつかん いき", "sentence_source": "generated"}, {"text": "地質が悪ければ、高い建物は建てられない。", "target_word": "地質", "complexity_tier": "T4", "furigana": "ちしつ わるければ たかい たてもの たてられない", "sentence_source": "generated"}, {"text": "先生に地質の調べ方を教えてもらった。", "target_word": "地質", "complexity_tier": "T4", "furigana": "せんせい ちしつ しらべかた おしえて", "sentence_source": "generated"}, {"text": "山と海では地質がまったく違うので、そこに住む生き物も大きく違っている。", "target_word": "地質", "complexity_tier": "T5", "furigana": "やま うみ ちしつ ちがう す いきもの おおきく ちがって", "sentence_source": "generated"}], "morphological_forms": [{"form": "地質学", "label": "派生"}, {"form": "地質調査", "label": "派生"}, {"form": "地質時代", "label": "派生"}, {"form": "地質学者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 地面の石や土のようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d4c905-0266-40e0-97e9-98715a34a555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38795, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間の意図や手によって行われること。自然の力ではなく、人間の活動によること。", "primary_collocate": null, "pronunciation": "じんい", "ipa": "d͡ʑiɴi", "syllable_count": 3, "sentences": [{"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "人為", "complexity_tier": "T6", "furigana": "じんいてき よういん たいきちゅう ほうしゅつ かじょう おんしつこうか ほうしゃきょうせいりょく へんか ぜんきゅうきぼ きこうへんどう かそく", "sentence_source": "mined"}, {"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "人為", "complexity_tier": "T6", "furigana": "りくつ ださん じんいてき おもわく かいざい よち せいめい こんげんてき かつぼう がんぜん じぶつ たいする じゅんすい じゅよう", "sentence_source": "mined"}, {"text": "これは人為だ。", "target_word": "人為", "complexity_tier": "T1", "furigana": "じんい", "sentence_source": "generated"}, {"text": "火事は人為ではありません。", "target_word": "人為", "complexity_tier": "T2", "furigana": "かじ じんい", "sentence_source": "generated"}, {"text": "人為の影響を調べました。", "target_word": "人為", "complexity_tier": "T2", "furigana": "じんい えいきょう しらべ", "sentence_source": "generated"}, {"text": "人為によるミスを減らしている。", "target_word": "人為", "complexity_tier": "T3", "furigana": "じんい へらして", "sentence_source": "generated"}, {"text": "自然の力ではなく、人為が加わった結果だ。", "target_word": "人為", "complexity_tier": "T3", "furigana": "しぜん ちから じんい くわわった けっか", "sentence_source": "generated"}, {"text": "人為が加えられていない自然の森が残っている。", "target_word": "人為", "complexity_tier": "T4", "furigana": "じんい くわえられて しぜん もり のこって", "sentence_source": "generated"}, {"text": "人為を排せば、本来の姿が見えてくるだろう。", "target_word": "人為", "complexity_tier": "T4", "furigana": "じんい はいせば ほんらい すがた みえて", "sentence_source": "generated"}, {"text": "この景色は自然にできたように見えるが、実は人為的に作られたものだ。", "target_word": "人為的に", "complexity_tier": "T5", "furigana": "けしき しぜん みえる じつ じんいてき つくられた", "sentence_source": "generated"}], "morphological_forms": [{"form": "人為的", "label": "派生"}, {"form": "人為的に", "label": "派生"}, {"form": "人為的ミス", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 人間の意図による行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d4c905-0266-40e0-97e9-98715a34a555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38794, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人がわざとすること。自然のままではなく、人が考えてすること。", "primary_collocate": null, "pronunciation": "じんい", "ipa": "d͡ʑiɴi", "syllable_count": 3, "sentences": [{"text": "人為ではない。", "target_word": "人為", "complexity_tier": "T1", "furigana": "じんい", "sentence_source": "generated"}, {"text": "人為を感じる。", "target_word": "人為", "complexity_tier": "T1", "furigana": "じんい かんじる", "sentence_source": "generated"}, {"text": "この池は人為のものです。", "target_word": "人為", "complexity_tier": "T2", "furigana": "いけ じんい", "sentence_source": "generated"}, {"text": "人為の跡が見えます。", "target_word": "人為", "complexity_tier": "T2", "furigana": "じんい あと みえ", "sentence_source": "generated"}, {"text": "自然と人為は違います。", "target_word": "人為", "complexity_tier": "T2", "furigana": "しぜん じんい ちがい", "sentence_source": "generated"}, {"text": "人為ではなく、自然にできた形だ。", "target_word": "人為", "complexity_tier": "T3", "furigana": "じんい しぜん かたち", "sentence_source": "generated"}, {"text": "人為を加えないで、自然のまま育てている。", "target_word": "人為", "complexity_tier": "T3", "furigana": "じんい くわえない しぜん そだてて", "sentence_source": "generated"}, {"text": "人為が加われば、森の姿は少しずつ変わる。", "target_word": "人為", "complexity_tier": "T4", "furigana": "じんい くわわれば もり すがた すこし かわる", "sentence_source": "generated"}, {"text": "人為によって作られた池だと言われている。", "target_word": "人為", "complexity_tier": "T4", "furigana": "じんい つくられた いけ いわれて", "sentence_source": "generated"}, {"text": "自然のように見える庭も、実は人為を重ねて作られたものかもしれない。", "target_word": "人為", "complexity_tier": "T5", "furigana": "しぜん みえる にわ じつ じんい かさねて つくられた", "sentence_source": "generated"}], "morphological_forms": [{"form": "人為的", "label": "派生"}, {"form": "人為的に", "label": "派生"}, {"form": "人為的ミス", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が意図して行うこと", "collocate_grounding": {"status": "no_source"