INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51996, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物を壊したり、組織や秩序を乱したりすること。", "primary_collocate": null, "pronunciation": "はかい", "ipa": "hakai", "syllable_count": 3, "sentences": [{"text": "しかし、産業革命以降の急激な人間活動、とりわけ化石燃料の大量消費と森林破壊は、この循環に深刻な破綻をもたらした。", "target_word": "破壊", "complexity_tier": "T6", "furigana": "さんぎょうかくめい いこう きゅうげき にんげんかつどう かせきねんりょう たいりょうしょうひ しんりん はかい じゅんかん しんこく はたん", "sentence_source": "mined"}, {"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "破壊", "complexity_tier": "T6", "furigana": "ふかくじつせい たかい ぎじゅつてき かだい いどむ きぎょうか たいし きょうきゅう かれら しじょう しっぱい ほかん はかいてき ほうが はぐくむ", "sentence_source": "mined"}, {"text": "橋を破壊した。", "target_word": "破壊", "complexity_tier": "T1", "furigana": "はし はかい", "sentence_source": "generated"}, {"text": "戦争は町を破壊しました。", "target_word": "破壊", "complexity_tier": "T2", "furigana": "せんそう まち はかい", "sentence_source": "generated"}, {"text": "破壊は止まりません。", "target_word": "破壊", "complexity_tier": "T2", "furigana": "はかい とまり", "sentence_source": "generated"}, {"text": "古い建物を破壊している作業が続いている。", "target_word": "破壊", "complexity_tier": "T3", "furigana": "ふるい たてもの はかい さぎょう つづいて", "sentence_source": "generated"}, {"text": "自然の破壊を止めたいと考えている。", "target_word": "破壊", "complexity_tier": "T3", "furigana": "しぜん はかい とめたい かんがえて", "sentence_source": "generated"}, {"text": "台風で多くの家が破壊された。", "target_word": "破壊", "complexity_tier": "T4", "furigana": "たいふう おおく いえ はかい", "sentence_source": "generated"}, {"text": "組織の秩序を破壊すれば、もとには戻せない。", "target_word": "破壊", "complexity_tier": "T4", "furigana": "そしき ちつじょ はかい もと もどせない", "sentence_source": "generated"}, {"text": "強い爆発によって建物が破壊され、周りの道路も使えなくなってしまった。", "target_word": "破壊", "complexity_tier": "T5", "furigana": "つよい ばくはつ たてもの はかい まわり どうろ つかえなく", "sentence_source": "generated"}], "morphological_forms": [{"form": "破壊する", "label": "活用"}, {"form": "破壊した", "label": "活用"}, {"form": "破壊される", "label": "活用"}, {"form": "破壊的", "label": "派生"}, {"form": "破壊力", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物や秩序を壊し乱すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 萌芽 (Zipf 2.48)']::text[], 'b7d4c905-0266-40e0-97e9-98715a34a555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51995, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "こわすこと。ものをこわして、ばらばらにすること。", "primary_collocate": null, "pronunciation": "はかい", "ipa": "hakai", "syllable_count": 3, "sentences": [{"text": "破壊はだめだ。", "target_word": "破壊", "complexity_tier": "T1", "furigana": "はかい", "sentence_source": "generated"}, {"text": "ものを破壊する。", "target_word": "破壊", "complexity_tier": "T1", "furigana": "はかい", "sentence_source": "generated"}, {"text": "子どもがおもちゃを破壊しました。", "target_word": "破壊", "complexity_tier": "T2", "furigana": "こども はかい", "sentence_source": "generated"}, {"text": "ハンマーで箱を破壊しました。", "target_word": "破壊", "complexity_tier": "T2", "furigana": "はこ はかい", "sentence_source": "generated"}, {"text": "車の窓を破壊して、中に入った。", "target_word": "破壊", "complexity_tier": "T3", "furigana": "くるま まど はかい なか はいった", "sentence_source": "generated"}, {"text": "機械を破壊してはいけません。", "target_word": "破壊", "complexity_tier": "T3", "furigana": "きかい はかい", "sentence_source": "generated"}, {"text": "破壊されたおもちゃを直している。", "target_word": "破壊", "complexity_tier": "T4", "furigana": "はかい なおして", "sentence_source": "generated"}, {"text": "強い風で屋根が破壊されてしまった。", "target_word": "破壊", "complexity_tier": "T4", "furigana": "つよい かぜ やね はかい", "sentence_source": "generated"}, {"text": "壁を破壊すれば、中の様子がわかる。", "target_word": "破壊", "complexity_tier": "T4", "furigana": "かべ はかい なか ようす", "sentence_source": "generated"}, {"text": "古い建物を破壊する前に、中のものをすべて外に出しておかなければならない。", "target_word": "破壊", "complexity_tier": "T5", "furigana": "ふるい たてもの はかい まえ なか そと だして", "sentence_source": "generated"}], "morphological_forms": [{"form": "破壊する", "label": "活用"}, {"form": "破壊した", "label": "活用"}, {"form": "破壊される", "label": "活用"}, {"form": "破壊的", "label": "派生"}, {"form": "破壊力", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物を壊してばらばらにすること", "collocate_gr