INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35621, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "グローバル", "is_correct": true, "explanation": "正解。「ぐろーばる」と読む。"}, {"text": "グローブ", "is_correct": false, "explanation": "「グローブ」は音が似ているが別の語。"}, {"text": "クローバー", "is_correct": false, "explanation": "「クローバー」は音が似ているが別の語。"}, {"text": "グローリー", "is_correct": false, "explanation": "「グローリー」は音が似ているが別の語。"}], "explanations": {"グローバル": "正解。「ぐろーばる」と読む。", "グローブ": "「グローブ」は音が似ているが別の語。", "クローバー": "「クローバー」は音が似ているが別の語。", "グローリー": "「グローリー」は音が似ているが別の語。"}, "sentence_index": null, "correct_answer": "グローバル"}, "level_3": {"options": [{"text": "グローバルな", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "清潔な", "is_correct": false, "explanation": "「清潔な」では文の意味が通らない。"}, {"text": "温暖な", "is_correct": false, "explanation": "「温暖な」では文の意味が通らない。"}, {"text": "素朴な", "is_correct": false, "explanation": "「素朴な」では文の意味が通らない。"}], "explanations": {"グローバルな": "正解。文脈に合う。", "清潔な": "「清潔な」では文の意味が通らない。", "温暖な": "「温暖な」では文の意味が通らない。", "素朴な": "「素朴な」では文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "グローバルな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の天気はグローバルです。", "explanation": "天気に使うのは不自然で、語義の誤用。"}, {"text": "彼はグローバルを歩きました。", "explanation": "「グローバル」は場所ではなく、助詞の使い方が誤り。"}, {"text": "グローバルな卵を食べました。", "explanation": "卵のような物に「グローバルな」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfd2beb-4f1d-4e2b-9a73-af465586d396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
