INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39469, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物事が新たな段階や状態に移る時、その変化を受け入れること。", "primary_collocate": null, "pronunciation": "むかえる", "ipa": "mukaeɾɯ", "syllable_count": 4, "sentences": [{"text": "かつては安定していた生態系のサイクルが、現代文明の経済活動によって歪められ、その修復は極めて困難な局面を迎えている。", "target_word": "迎えている", "complexity_tier": "T6", "furigana": "むかえている", "sentence_source": "mined"}, {"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "迎える", "complexity_tier": "T6", "furigana": "むかえる", "sentence_source": "mined"}, {"text": "春を迎える。", "target_word": "迎える", "complexity_tier": "T1", "furigana": "むかえる", "sentence_source": "generated"}, {"text": "彼は十歳を迎えた。", "target_word": "迎えた", "complexity_tier": "T1", "furigana": "むかえた", "sentence_source": "generated"}, {"text": "来月、私は二十歳を迎えます。", "target_word": "迎えます", "complexity_tier": "T2", "furigana": "むかえます", "sentence_source": "generated"}, {"text": "店は開店十周年を迎えました。", "target_word": "迎えました", "complexity_tier": "T2", "furigana": "むかえました", "sentence_source": "generated"}, {"text": "新しい年を迎えて、家族で初詣に行った。", "target_word": "迎えて", "complexity_tier": "T3", "furigana": "むかえて", "sentence_source": "generated"}, {"text": "町は今、大きな変化の時期を迎えている。", "target_word": "迎えている", "complexity_tier": "T3", "furigana": "むかえている", "sentence_source": "generated"}, {"text": "このまま冬を迎えれば、山道は雪で閉ざされてしまう。", "target_word": "迎えれば", "complexity_tier": "T4", "furigana": "むかえれば", "sentence_source": "generated"}, {"text": "人生の大きな転機を迎える人は、不安と期待の両方を感じるものだ。", "target_word": "迎える", "complexity_tier": "T5", "furigana": "むかえる", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎えた", "label": "活用"}, {"form": "迎えて", "label": "活用"}, {"form": "迎えられる", "label": "活用"}, {"form": "迎え", "label": "派生"}, {"form": "お迎え", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 新たな時期や状態に入る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9f74-4908be2cfbe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39468, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "むかえにいくこと。または、だれかがくるのをまつこと。", "primary_collocate": null, "pronunciation": "むかえる", "ipa": "mukaeɾɯ", "syllable_count": 4, "sentences": [{"text": "駅で友達を迎える。", "target_word": "迎える", "complexity_tier": "T1", "furigana": "むかえる", "sentence_source": "generated"}, {"text": "母が玄関で迎えた。", "target_word": "迎えた", "complexity_tier": "T1", "furigana": "むかえた", "sentence_source": "generated"}, {"text": "空港まで客を迎えに行きます。", "target_word": "迎え", "complexity_tier": "T2", "furigana": "むかえ", "sentence_source": "generated"}, {"text": "先生は笑顔で私たちを迎えました。", "target_word": "迎えました", "complexity_tier": "T2", "furigana": "むかえました", "sentence_source": "generated"}, {"text": "犬は毎日、玄関で私を迎えてくれる。", "target_word": "迎えて", "complexity_tier": "T3", "furigana": "むかえて", "sentence_source": "generated"}, {"text": "お客さんを迎える準備はもうできた。", "target_word": "迎える", "complexity_tier": "T3", "furigana": "むかえる", "sentence_source": "generated"}, {"text": "雨の中、妹を駅まで迎えに行ってきた。", "target_word": "迎え", "complexity_tier": "T3", "furigana": "むかえ", "sentence_source": "generated"}, {"text": "もし雨が降れば、車で迎えに行くよ。", "target_word": "迎え", "complexity_tier": "T3", "furigana": "むかえ", "sentence_source": "generated"}, {"text": "大切なお客様を迎えるために、部屋をきれいに掃除させられた。", "target_word": "迎える", "complexity_tier": "T4", "furigana": "むかえる", "sentence_source": "generated"}, {"text": "遠くから来た親戚を、ホームで長い時間待ちながら迎えた。", "target_word": "迎えた", "complexity_tier": "T4", "furigana": "むかえた", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎えた", "label": "活用"}, {"form": "迎えて", "label": "活用"}, {"form": "迎えに", "label": "活用"}, {"form": "迎え", "label": "派生"}, {"form": "お迎え", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 来る人を出向いて迎える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9f74-4908be2cfbe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38449, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "細部にまで注意を払い、正確で詳しいさま。また、そのような性質。", "primary_collocate": null, "pronunciation": "せいち", "ipa": "seitɕi", "syllable_count": 3, "sentences": [{"text": "地球システムにおける炭素循環は、地質学的時間軸において精緻な均衡を保ってきた。", "target_word": "精緻な", "complexity_tier": "T5", "furigana": "せいちな", "sentence_source": "mined"}, {"text": "ベル・エポック期、アトリエにおける職人の手指による精緻な刺繍とドレープは、身体を包み込む芸術として確立された。", "target_word": "精緻な", "complexity_tier": "T6", "furigana": "せいちな", "sentence_source": "mined"}, {"text": "この人形は精緻だ。", "target_word": "精緻だ", "complexity_tier": "T1", "furigana": "せいちだ", "sentence_source": "generated"}, {"text": "この時計は精緻な作りです。", "target_word": "精緻な", "complexity_tier": "T2", "furigana": "せいちな", "sentence_source": "generated"}, {"text": "彼の計画はとても精緻です。", "target_word": "精緻です", "complexity_tier": "T2", "furigana": "せいちです", "sentence_source": "generated"}, {"text": "職人が精緻な細工をほどこした箱を買った。", "target_word": "精緻な", "complexity_tier": "T3", "furigana": "せいちな", "sentence_source": "generated"}, {"text": "精緻に描かれた地図を見て、みんなが驚いた。", "target_word": "精緻に", "complexity_tier": "T3", "furigana": "せいちに", "sentence_source": "generated"}, {"text": "その模型は、細部まで精緻だったと言われている。", "target_word": "精緻だった", "complexity_tier": "T4", "furigana": "せいちだった", "sentence_source": "generated"}, {"text": "計画がもっと精緻であれば、失敗は防げたかもしれない。", "target_word": "精緻であれば", "complexity_tier": "T4", "furigana": "せいちであれば", "sentence_source": "generated"}, {"text": "顕微鏡のない時代に、これほど精緻な彫刻を手で仕上げたとは信じがたい。", "target_word": "精緻な", "complexity_tier": "T5", "furigana": "せいちな", "sentence_source": "generated"}], "morphological_forms": [{"form": "精緻な", "label": "活用"}, {"form": "精緻に", "label": "活用"}, {"form": "精緻だ", "label": "活用"}, {"form": "精緻さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 細部まで正確で詳しいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9f74-4908be2cfbe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38448, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "細かいところまで、とてもていねいに作られていること。", "primary_collocate": null, "pronunciation": "せいち", "ipa": "seitɕi", "syllable_count": 3, "sentences": [{"text": "この人形は精緻だ。", "target_word": "精緻だ", "complexity_tier": "T1", "furigana": "せいちだ", "sentence_source": "generated"}, {"text": "精緻な模型を買いました。", "target_word": "精緻な", "complexity_tier": "T2", "furigana": "せいちな", "sentence_source": "generated"}, {"text": "この刺繍はとても精緻です。", "target_word": "精緻です", "complexity_tier": "T2", "furigana": "せいちです", "sentence_source": "generated"}, {"text": "彼は精緻に作られた時計を持っています。", "target_word": "精緻に", "complexity_tier": "T3", "furigana": "せいちに", "sentence_source": "generated"}, {"text": "祖父は精緻な細工の箱を作ってくれた。", "target_word": "精緻な", "complexity_tier": "T3", "furigana": "せいちな", "sentence_source": "generated"}, {"text": "この地図は細かいところまで精緻に描かれている。", "target_word": "精緻に", "complexity_tier": "T4", "furigana": "せいちに", "sentence_source": "generated"}, {"text": "その彫刻は精緻だったので、多くの人が足を止めて見入った。", "target_word": "精緻だったので", "complexity_tier": "T4", "furigana": "せいちだったので", "sentence_source": "generated"}, {"text": "もっと精緻であれば、この模型は賞を取れたかもしれない。", "target_word": "精緻であれば", "complexity_tier": "T4", "furigana": "せいちであれば", "sentence_source": "generated"}, {"text": "小さな部品がひとつずつ精緻に組み合わされた機械は、まるで生きているかのように動く。", "target_word": "精緻に", "complexity_tier": "T6", "furigana": "せいちに", "sentence_source": "generated"}, {"text": "職人の精緻な手仕事は、機械には決してまねのできない美しさを持っている。", "target_word": "精緻な", "complexity_tier": "T5", "furigana": "せいちな", "sentence_source": "generated"}], "morphological_forms": [{"form": "精緻な", "label": "活用"}, {"form": "精緻に", "label": "活用"}, {"form": "精緻だ", "label": "活用"}, {"form": "精緻さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 細部まで丁寧に作られたさま", "collocate_grou