INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38851, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある状態を変えずに続ける。", "primary_collocate": null, "pronunciation": "たもつ", "ipa": "tamotsɯ", "syllable_count": 3, "sentences": [{"text": "地球システムにおける炭素循環は、地質学的時間軸において精緻な均衡を保ってきた。", "target_word": "保って", "complexity_tier": "T5", "furigana": "たもって", "sentence_source": "mined"}, {"text": "教師の指示のもと、静寂を保ちつつも頭脳をフル回転させる学習の時間。", "target_word": "保ち", "complexity_tier": "T5", "furigana": "たもち", "sentence_source": "mined"}, {"text": "笑顔を保つ。", "target_word": "保つ", "complexity_tier": "T1", "furigana": "たもつ", "sentence_source": "generated"}, {"text": "部屋の温度を一定に保ちます。", "target_word": "保ちます", "complexity_tier": "T2", "furigana": "たもちます", "sentence_source": "generated"}, {"text": "毎日運動して、健康を保っています。", "target_word": "保っています", "complexity_tier": "T3", "furigana": "たもっています", "sentence_source": "generated"}, {"text": "彼女は最後まで落ち着きを保って話した。", "target_word": "保って", "complexity_tier": "T3", "furigana": "たもって", "sentence_source": "generated"}, {"text": "冷蔵庫は食べ物を新鮮に保つことができる。", "target_word": "保つ", "complexity_tier": "T3", "furigana": "たもつ", "sentence_source": "generated"}, {"text": "相手との距離を保たなければ、トラブルになりかねない。", "target_word": "保たなければ", "complexity_tier": "T4", "furigana": "たもたなければ", "sentence_source": "generated"}, {"text": "水温が保たれているおかげで、魚は冬も元気に過ごせた。", "target_word": "保たれている", "complexity_tier": "T4", "furigana": "たもたれている", "sentence_source": "generated"}, {"text": "長年にわたって品質を保ち続けてきた店だからこそ、客が絶えないのだろう。", "target_word": "保ち", "complexity_tier": "T5", "furigana": "たもち", "sentence_source": "generated"}], "morphological_forms": [{"form": "保った", "label": "活用"}, {"form": "保って", "label": "活用"}, {"form": "保たない", "label": "活用"}, {"form": "保てる", "label": "活用"}, {"form": "保たれる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | ある状態を変えず続ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9f74-4908be2cfbe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38850, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、そのままの状態のままにしておく。", "primary_collocate": null, "pronunciation": "たもつ", "ipa": "tamotsɯ", "syllable_count": 3, "sentences": [{"text": "水を冷たく保つ。", "target_word": "保つ", "complexity_tier": "T1", "furigana": "たもつ", "sentence_source": "generated"}, {"text": "氷で肉を冷たく保ちます。", "target_word": "保ちます", "complexity_tier": "T2", "furigana": "たもちます", "sentence_source": "generated"}, {"text": "髪を短く保ち、毎朝きちんと整えている。", "target_word": "保ち", "complexity_tier": "T3", "furigana": "たもち", "sentence_source": "generated"}, {"text": "祖父は庭を一年中きれいに保っていた。", "target_word": "保って", "complexity_tier": "T3", "furigana": "たもって", "sentence_source": "generated"}, {"text": "古い家の形をそのまま保って住んでいる。", "target_word": "保って", "complexity_tier": "T3", "furigana": "たもって", "sentence_source": "generated"}, {"text": "毛布で足を温かく保つと、よく眠れる。", "target_word": "保つ", "complexity_tier": "T3", "furigana": "たもつ", "sentence_source": "generated"}, {"text": "魚を新鮮に保つためには、すぐに氷で冷やさなければならない。", "target_word": "保つ", "complexity_tier": "T4", "furigana": "たもつ", "sentence_source": "generated"}, {"text": "この寺は、江戸時代の姿を保ったまま、今も使われている。", "target_word": "保った", "complexity_tier": "T4", "furigana": "たもった", "sentence_source": "generated"}, {"text": "ワインは温度を一定に保てる地下の倉庫に置くと、味が落ちにくい。", "target_word": "保てる", "complexity_tier": "T5", "furigana": "たもてる", "sentence_source": "generated"}, {"text": "母は部屋をいつもきれいに保っている。", "target_word": "保って", "complexity_tier": "T3", "furigana": "たもって", "sentence_source": "generated"}], "morphological_forms": [{"form": "保った", "label": "活用"}, {"form": "保って", "label": "活用"}, {"form": "保たない", "label": "活用"}, {"form": "保てる", "label": "活用"}, {"form": "保たれる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 物をそのままの状態に置く", "collocate_grounding": {"status": "no_s