INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36323, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "方法や理由をたずねる疑問詞。様態や手段、理由を表す。", "primary_collocate": null, "pronunciation": "どう", "ipa": "doː", "syllable_count": 2, "sentences": [{"text": "我々は、この不可逆的な変化の連鎖をどう受け止めるべきか、文明の存続をかけて抜本的な転換を迫られているのである。", "target_word": "どう", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "どう", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "どうする？", "target_word": "どう", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "この漢字はどう読みますか。", "target_word": "どう", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "駅へはどう行けばいいですか。", "target_word": "どう", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "お茶はどうですか。", "target_word": "どう", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "先生の質問に、どう答えたらいいか分からない。", "target_word": "どう", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "私がどう説明しても、彼は納得してくれなかった。", "target_word": "どう", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "この問題をどう解決すべきか、会議で長く議論された。", "target_word": "どう", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "外国での生活が、人の考え方をどう変えるのかを自分で確かめたい。", "target_word": "どう", "complexity_tier": "T5", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "どうして", "label": "派生"}, {"form": "どうやって", "label": "派生"}, {"form": "どうしても", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | 方法や様子をたずねる語", "collocate_grounding": {"status": "no