INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36322, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「どのような方法で」という意味で、やり方や理由を聞くときに使う言葉。", "primary_collocate": null, "pronunciation": "どう", "ipa": "doː", "syllable_count": 2, "sentences": [{"text": "どうしますか。", "target_word": "どう", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "これはどう読むの？", "target_word": "どう", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "この料理はどう食べますか。", "target_word": "どう", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "学校へはどう行きますか。", "target_word": "どう", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "この言葉は英語でどう言いますか。", "target_word": "どう", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "先生に、どう謝ればいいか分からない。", "target_word": "どう", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "ケーキはどう作ればおいしくなりますか。", "target_word": "どう", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "駅までどう行くのか、地図で見せてもらった。", "target_word": "どう", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この問題をどう考えればいいか分からない。", "target_word": "どう", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この機械をどう使うのか、係の人が教えてくれた。", "target_word": "どう", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "どうして", "label": "派生"}, {"form": "どうやって", "label": "派生"}, {"form": "どうしても", "label": "派生"}], "register": "plain", "sense_fingerprint": "副詞 | やり方を聞くときの語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9