INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51598, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物事の表面だけでなく、内部や本質にまで深く入り込んでいる様子。また、考えや感情などが簡単には理解できないほど深いこと。", "primary_collocate": null, "pronunciation": "おくぶかい", "ipa": "okɯbɯkai", "syllable_count": 5, "sentences": [{"text": "さらに、アミノ酸や有機酸が複雑に絡み合い、主食に奥深い風味と旨味の層を付与する。", "target_word": "奥深い", "complexity_tier": "T5", "furigana": "おくぶかい", "sentence_source": "mined"}, {"text": "森の奥深くに佇む、その赤いドアの小さな家は、かつて祖母が一人で暮らしていた場所だ。", "target_word": "奥深く", "complexity_tier": "T6", "furigana": "おくぶかく", "sentence_source": "mined"}, {"text": "この話は奥深い。", "target_word": "奥深い", "complexity_tier": "T1", "furigana": "おくぶかい", "sentence_source": "generated"}, {"text": "この映画は奥深いです。", "target_word": "奥深いです", "complexity_tier": "T2", "furigana": "おくぶかいです", "sentence_source": "generated"}, {"text": "この本の内容は奥深くて面白いです。", "target_word": "奥深くて", "complexity_tier": "T2", "furigana": "おくぶかくて", "sentence_source": "generated"}, {"text": "日本茶の世界は、知れば知るほど奥深い。", "target_word": "奥深い", "complexity_tier": "T3", "furigana": "おくぶかい", "sentence_source": "generated"}, {"text": "奥深い考えを持つ人と話すと、勉強になる。", "target_word": "奥深い", "complexity_tier": "T3", "furigana": "おくぶかい", "sentence_source": "generated"}, {"text": "奥深い意味を持つ言葉ほど、簡単には訳せないものだ。", "target_word": "奥深い", "complexity_tier": "T4", "furigana": "おくぶかい", "sentence_source": "generated"}, {"text": "芸術の世界は奥深く、一生かけても学びきれない。", "target_word": "奥深く", "complexity_tier": "T4", "furigana": "おくぶかく", "sentence_source": "generated"}, {"text": "彼の作品は一見単純に見えたが、読み返すとやはり奥深かった。", "target_word": "奥深かった", "complexity_tier": "T4", "furigana": "おくぶかかった", "sentence_source": "generated"}], "morphological_forms": [{"form": "奥深く", "label": "活用"}, {"form": "奥深かった", "label": "活用"}, {"form": "奥深くない", "label": "活用"}, {"form": "奥深くて", "label": "活用"}, {"form": "奥深さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 内部や本質まで深いさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9f74-4908be2cfbe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51597, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物事の表面だけではなく、もっと深いところまであること。", "primary_collocate": null, "pronunciation": "おくぶかい", "ipa": "okɯbɯkai", "syllable_count": 5, "sentences": [{"text": "山は奥深い。", "target_word": "奥深い", "complexity_tier": "T1", "furigana": "おくぶかい", "sentence_source": "generated"}, {"text": "海の奥深くへ潜った。", "target_word": "奥深く", "complexity_tier": "T1", "furigana": "おくぶかく", "sentence_source": "generated"}, {"text": "その洞窟はとても奥深いです。", "target_word": "奥深いです", "complexity_tier": "T2", "furigana": "おくぶかいです", "sentence_source": "generated"}, {"text": "村は山の奥深くにあります。", "target_word": "奥深く", "complexity_tier": "T2", "furigana": "おくぶかく", "sentence_source": "generated"}, {"text": "奥深い谷で、道に迷ってしまった。", "target_word": "奥深い", "complexity_tier": "T2", "furigana": "おくぶかい", "sentence_source": "generated"}, {"text": "古い寺は奥深い山の中に建っている。", "target_word": "奥深い", "complexity_tier": "T3", "furigana": "おくぶかい", "sentence_source": "generated"}, {"text": "川の水は、奥深く染み込んでいった。", "target_word": "奥深く", "complexity_tier": "T3", "furigana": "おくぶかく", "sentence_source": "generated"}, {"text": "この井戸は、とても奥深いところまで掘られている。", "target_word": "奥深い", "complexity_tier": "T4", "furigana": "おくぶかい", "sentence_source": "generated"}, {"text": "井戸の水は奥深く、手を伸ばしても届かなかった。", "target_word": "奥深く", "complexity_tier": "T4", "furigana": "おくぶかく", "sentence_source": "generated"}, {"text": "森の奥深くまで進むにつれて、空気は冷たく、静かになっていった。", "target_word": "奥深く", "complexity_tier": "T5", "furigana": "おくぶかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "奥深く", "label": "活用"}, {"form": "奥深かった", "label": "活用"}, {"form": "奥深くない", "label": "活用"}, {"form": "奥深くて", "label": "活用"}, {"form": "奥深さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 表面でなく深いところ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9f74-4908be2cfbe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53394, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "甘味・酸味・塩味・苦味と並ぶ五つの基本味のことで、コクや深みを感じるおいしい味。", "primary_collocate": null, "pronunciation": "うまみ", "ipa": "ɯmami", "syllable_count": 3, "sentences": [{"text": "さらに、アミノ酸や有機酸が複雑に絡み合い、主食に奥深い風味と旨味の層を付与する。", "target_word": "旨味", "complexity_tier": "T5", "furigana": "うまみ", "sentence_source": "mined"}, {"text": "旨味がある。", "target_word": "旨味", "complexity_tier": "T1", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "このスープは旨味が強いです。", "target_word": "旨味", "complexity_tier": "T2", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "昆布は旨味のもとです。", "target_word": "旨味", "complexity_tier": "T2", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "旨味を感じますか。", "target_word": "旨味", "complexity_tier": "T1", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "肉を焼くと、旨味が外に逃げにくくなる。", "target_word": "旨味", "complexity_tier": "T3", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "トマトには旨味がたくさん入っている。", "target_word": "旨味", "complexity_tier": "T3", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "日本料理では、だしの旨味を生かす工夫がされている。", "target_word": "旨味", "complexity_tier": "T4", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "旨味は、甘味や塩味と並ぶ基本の味として知られている。", "target_word": "旨味", "complexity_tier": "T4", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "昆布や鰹節から出る旨味が、味噌汁にやさしい深みを与えている。", "target_word": "旨味", "complexity_tier": "T4", "furigana": "うまみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "旨み", "label": "派生"}, {"form": "旨味成分", "label": "派生"}, {"form": "旨味調味料", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 五つの基本味の一つで深いおいしさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9f74-4908be2cfbe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53393, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お肉や野菜の、おいしい味のことです。", "primary_collocate": null, "pronunciation": "うまみ", "ipa": "ɯmami", "syllable_count": 3, "sentences": [{"text": "肉の旨味を味わう。", "target_word": "旨味", "complexity_tier": "T1", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "この野菜は旨味があります。", "target_word": "旨味", "complexity_tier": "T2", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "焼いた魚の旨味が口に広がった。", "target_word": "旨味", "complexity_tier": "T2", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "トマトを煮ると旨味が出ます。", "target_word": "旨味", "complexity_tier": "T2", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "母の作るスープは、野菜の旨味がよく出ている。", "target_word": "旨味", "complexity_tier": "T3", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "肉は焼きすぎると旨味が逃げてしまう。", "target_word": "旨味", "complexity_tier": "T3", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "きのこは旨味が強いので、塩だけでもおいしい。", "target_word": "旨味", "complexity_tier": "T3", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "旨味を逃がさないように、弱い火でゆっくり焼いた。", "target_word": "旨味", "complexity_tier": "T4", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "野菜をじっくり煮込むと、素材の旨味が引き出される。", "target_word": "旨味", "complexity_tier": "T4", "furigana": "うまみ", "sentence_source": "generated"}, {"text": "新鮮な魚は、余計な味をつけなくても、自然な旨味を十分に楽しむことができる。", "target_word": "旨味", "complexity_tier": "T5", "furigana": "うまみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "旨み", "label": "派生"}, {"form": "旨味成分", "label": "派生"}, {"form": "旨味調味料", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 肉や野菜のおいしい味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579ecf07-d584-4361-9f74-4908be2cfbe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39469, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迎える", "is_correct": true, "explanation": "「迎える」が聞こえた語そのもの。"}, {"text": "かかえる", "is_correct": false, "explanation": "「かかえる」は別の語で、音が違う。"}, {"text": "ひかえる", "is_correct": false, "explanation": "「ひかえる」は別の語で、音が違う。"}, {"text": "つかえる", "is_correct": false, "explanation": "「つかえる」は別の語で、音が違う。"}], "explanations": {"迎える": "「迎える」が聞こえた語そのもの。", "かかえる": "「かかえる」は別の語で、音が違う。", "ひかえる": "「ひかえる」は別の語で、音が違う。", "つかえる": "「つかえる」は別の語で、音が違う。"}, "sentence_index": null, "correct_answer": "迎える"}, "level_3": {"options": [{"text": "迎えている", "is_correct": true, "explanation": "「迎えている」が空所に合う。"}, {"text": "洗っている", "is_correct": false, "explanation": "「洗っている」は意味が合わず不自然。"}, {"text": "折っている", "is_correct": false, "explanation": "「折っている」は意味が合わず不自然。"}, {"text": "拾っている", "is_correct": false, "explanation": "「拾っている」は意味が合わず不自然。"}], "explanations": {"迎えている": "「迎えている」が空所に合う。", "洗っている": "「洗っている」は意味が合わず不自然。", "折っている": "「折っている」は意味が合わず不自然。", "拾っている": "「拾っている」は意味が合わず不自然。"}, "sentence_index": 0, "correct_answer": "迎えている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は十歳に迎えた。", "explanation": "時期や年齢は「を迎える」の形で使い、「に」は合わない。"}, {"text": "彼は昨日、公園で友達の本を迎えた。", "explanation": "「迎える」は物を受け取る意味では使えない。"}, {"text": "彼は十歳を迎えるた。", "explanation": "「迎える」の過去形は「迎えた」で、「迎えるた」とはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3003610-a773-4f07-9d6e-e880da648b7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
