INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38449, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精緻", "is_correct": true, "explanation": "「精緻」が聞こえた語そのもの。"}, {"text": "せいじ", "is_correct": false, "explanation": "「せいじ」は別の語で、音が違う。"}, {"text": "せいき", "is_correct": false, "explanation": "「せいき」は別の語で、音が違う。"}, {"text": "せいり", "is_correct": false, "explanation": "「せいり」は別の語で、音が違う。"}, {"text": "せいか", "is_correct": false, "explanation": "「せいか」は別の語で、音が違う。"}], "explanations": {"精緻": "「精緻」が聞こえた語そのもの。", "せいじ": "「せいじ」は別の語で、音が違う。", "せいき": "「せいき」は別の語で、音が違う。", "せいり": "「せいり」は別の語で、音が違う。", "せいか": "「せいか」は別の語で、音が違う。"}, "sentence_index": null, "correct_answer": "精緻"}, "level_3": {"options": [{"text": "精緻な", "is_correct": true, "explanation": "「精緻な」が空所に合う。"}, {"text": "豊富な", "is_correct": false, "explanation": "「豊富な」は意味が合わず不自然。"}, {"text": "莫大な", "is_correct": false, "explanation": "「莫大な」は意味が合わず不自然。"}, {"text": "愉快な", "is_correct": false, "explanation": "「愉快な」は意味が合わず不自然。"}], "explanations": {"精緻な": "「精緻な」が空所に合う。", "豊富な": "「豊富な」は意味が合わず不自然。", "莫大な": "「莫大な」は意味が合わず不自然。", "愉快な": "「愉快な」は意味が合わず不自然。"}, "sentence_index": 0, "correct_answer": "精緻な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は風が精緻で、とても寒い。", "explanation": "精緻は風の強さには使えない。"}, {"text": "彼は精緻な気持ちで、毎日学校へ走って行く。", "explanation": "精緻は気持ちの様子を表す語ではない。"}, {"text": "この道は精緻に長くて、歩くのに疲れた。", "explanation": "精緻は長さの程度を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3003610-a773-4f07-9d6e-e880da648b7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
